CREATE SCHEMA obrigacoes51;
REVOKE ALL ON SCHEMA obrigacoes51 FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE obrigacoes51.manifesto(id integer PRIMARY KEY CHECK(id=1),assinatura text NOT NULL);
CREATE TABLE obrigacoes51.operacoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id integer NOT NULL REFERENCES public.users(id),chave uuid NOT NULL,contrato_id integer NOT NULL REFERENCES public.contratos(id) ON DELETE RESTRICT,request jsonb NOT NULL,hash_request text NOT NULL,antes jsonb NOT NULL,depois jsonb,resultado jsonb,hash_resultado text,concluida_em timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(user_id,chave),UNIQUE(user_id,id),CHECK(hash_request ~ '^[a-f0-9]{64}$'),CHECK((resultado IS NULL AND depois IS NULL AND concluida_em IS NULL AND hash_resultado IS NULL) OR (resultado IS NOT NULL AND depois IS NOT NULL AND concluida_em IS NOT NULL AND hash_resultado ~ '^[a-f0-9]{64}$')));
CREATE TABLE obrigacoes51.fences(user_id integer NOT NULL REFERENCES public.users(id),chave uuid NOT NULL,contrato_id integer NOT NULL REFERENCES public.contratos(id) ON DELETE RESTRICT,request jsonb NOT NULL,hash_request text NOT NULL CHECK(hash_request ~ '^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(user_id,chave));
CREATE TABLE obrigacoes51.adicionais(user_id integer NOT NULL,contrato_id integer NOT NULL REFERENCES public.contratos(id) ON DELETE RESTRICT,parcela_id integer PRIMARY KEY REFERENCES public.parcelas(id) ON DELETE RESTRICT,operacao48 uuid NOT NULL UNIQUE REFERENCES public.multimodal_operacoes(id) ON DELETE RESTRICT,numero integer NOT NULL CHECK(numero BETWEEN 1 AND 60),valor numeric(12,2) NOT NULL CHECK(valor>0),linha_inicial jsonb NOT NULL,hash_linha text NOT NULL CHECK(hash_linha ~ '^[a-f0-9]{64}$'),UNIQUE(contrato_id,numero),FOREIGN KEY(user_id,operacao48) REFERENCES public.multimodal_operacoes(user_id,id) ON DELETE RESTRICT);
CREATE TABLE obrigacoes51.cancelamentos(user_id integer NOT NULL,contrato_id integer NOT NULL REFERENCES public.contratos(id) ON DELETE RESTRICT,parcela_id integer PRIMARY KEY REFERENCES public.parcelas(id) ON DELETE RESTRICT,operacao_id uuid NOT NULL,obrigacao_registrada numeric(12,2) NOT NULL CHECK(obrigacao_registrada>0),valor_pago_preservado numeric(12,2) NOT NULL CHECK(valor_pago_preservado>=0),status_original text NOT NULL,FOREIGN KEY(user_id,operacao_id) REFERENCES obrigacoes51.operacoes(user_id,id) ON DELETE RESTRICT);
CREATE TABLE obrigacoes51.encerramentos(user_id integer NOT NULL,contrato_id integer PRIMARY KEY REFERENCES public.contratos(id) ON DELETE RESTRICT,operacao_id uuid NOT NULL,FOREIGN KEY(user_id,operacao_id) REFERENCES obrigacoes51.operacoes(user_id,id) ON DELETE RESTRICT);
CREATE TABLE obrigacoes51.arquivos(user_id integer NOT NULL,contrato_id integer NOT NULL REFERENCES public.contratos(id) ON DELETE RESTRICT,parcela_id integer REFERENCES public.parcelas(id) ON DELETE RESTRICT,operacao_id uuid NOT NULL,FOREIGN KEY(user_id,operacao_id) REFERENCES obrigacoes51.operacoes(user_id,id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX arquivo51_contrato ON obrigacoes51.arquivos(contrato_id) WHERE parcela_id IS NULL;
CREATE UNIQUE INDEX arquivo51_parcela ON obrigacoes51.arquivos(parcela_id) WHERE parcela_id IS NOT NULL;
CREATE FUNCTION obrigacoes51.hash(j jsonb) RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT encode(extensions.digest(j::text,'sha256'),'hex') $$;
CREATE FUNCTION obrigacoes51.dinheiro(s text) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN IF s IS NULL OR s !~ '^(0|[1-9][0-9]{0,9})\.[0-9]{2}$' THEN RAISE EXCEPTION '51 centavos textuais exatos obrigatórios' USING ERRCODE='22023'; END IF; RETURN s::numeric; END $$;
CREATE FUNCTION obrigacoes51.dia(s text) RETURNS date LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ DECLARE d date; BEGIN IF s IS NULL OR s !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION '51 DATE civil obrigatória' USING ERRCODE='22023'; END IF; d:=s::date; IF NOT isfinite(d) OR d NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' OR d::text<>s THEN RAISE EXCEPTION '51 DATE inválida' USING ERRCODE='22023'; END IF; RETURN d; END $$;
CREATE FUNCTION obrigacoes51.id(j jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN IF jsonb_typeof(j) IS DISTINCT FROM 'number' OR j::text !~ '^[1-9][0-9]{0,9}$' OR j::numeric>2147483647 THEN RAISE EXCEPTION '51 ID int32 positivo obrigatório' USING ERRCODE='22023'; END IF; RETURN j::text::integer; END $$;
CREATE FUNCTION obrigacoes51.proposta(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a text:=v->>'acao'; target jsonb; expected jsonb; amount numeric;
BEGIN
 IF v IS NULL OR jsonb_typeof(v) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '51 proposta estrita obrigatória' USING ERRCODE='22023'; END IF;
 IF a='adicionar' THEN
 expected:=jsonb_build_object('acao',a,'valor',v->>'valor','dataVencimento',v->>'dataVencimento','classificacao','obrigacao_adicional_nao_desembolsada');amount:=obrigacoes51.dinheiro(v->>'valor');PERFORM obrigacoes51.dia(v->>'dataVencimento');IF amount<=0 THEN RAISE EXCEPTION '51 valor positivo obrigatório' USING ERRCODE='22023';END IF;
 ELSIF a='editar' THEN
 expected:=jsonb_build_object('acao',a,'parcelaId',obrigacoes51.id(v->'parcelaId'));
 IF v ? 'novoValor' THEN amount:=obrigacoes51.dinheiro(v->>'novoValor');IF amount<=0 THEN RAISE EXCEPTION '51 valor positivo obrigatório' USING ERRCODE='22023';END IF;expected:=expected||jsonb_build_object('novoValor',v->>'novoValor');END IF;
 IF v ? 'novaDataVencimento' THEN PERFORM obrigacoes51.dia(v->>'novaDataVencimento');expected:=expected||jsonb_build_object('novaDataVencimento',v->>'novaDataVencimento');END IF;
 IF NOT(v ? 'novoValor' OR v ? 'novaDataVencimento') THEN RAISE EXCEPTION '51 valor e/ou data obrigatórios' USING ERRCODE='22023';END IF;
 ELSIF a IN('cancelar','arquivar') THEN
 target:=CASE v->'alvo'->>'tipo' WHEN 'contrato' THEN jsonb_build_object('tipo','contrato') WHEN 'parcela' THEN jsonb_build_object('tipo','parcela','parcelaId',obrigacoes51.id(v->'alvo'->'parcelaId')) ELSE NULL END;
 IF target IS NULL OR target IS DISTINCT FROM v->'alvo' THEN RAISE EXCEPTION '51 alvo fechado inválido' USING ERRCODE='22023';END IF;
 expected:=jsonb_build_object('acao',a,'alvo',target);IF a='cancelar' THEN expected:=expected||jsonb_build_object('reconhecoSemEstorno',true);END IF;
 ELSIF a='quitar' THEN amount:=obrigacoes51.dinheiro(v->>'valorRecebido');IF amount<=0 THEN RAISE EXCEPTION '51 dinheiro real positivo obrigatório' USING ERRCODE='22023';END IF;expected:=jsonb_build_object('acao',a,'contaCaixaId',obrigacoes51.id(v->'contaCaixaId'),'valorRecebido',v->>'valorRecebido','reconhecoDinheiroReal',true);
 ELSE RAISE EXCEPTION '51 ação inválida' USING ERRCODE='22023';END IF;
 IF expected IS DISTINCT FROM v THEN RAISE EXCEPTION '51 proposta exata/campos extras/consentimento inválidos' USING ERRCODE='22023';END IF;RETURN v;
END $$;
CREATE FUNCTION obrigacoes51.request(r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE e jsonb;
BEGIN
 IF r IS NULL OR jsonb_typeof(r) IS DISTINCT FROM 'object' OR coalesce(r->>'estadoHash','') !~ '^[a-f0-9]{64}$' OR r->>'motivo' IS NULL OR length(r->>'motivo') NOT BETWEEN 3 AND 500 OR r->>'motivo'<>btrim(r->>'motivo') THEN RAISE EXCEPTION '51 intenção estrita inválida' USING ERRCODE='22023';END IF;
 e:=jsonb_build_object('contratoId',obrigacoes51.id(r->'contratoId'),'proposta',obrigacoes51.proposta(r->'proposta'),'estadoHash',r->>'estadoHash','dataCalculo',obrigacoes51.dia(r->>'dataCalculo'),'motivo',r->>'motivo');IF e IS DISTINCT FROM r THEN RAISE EXCEPTION '51 request exato sem owner/chave/conta arbitrários' USING ERRCODE='22023';END IF;RETURN r;
END $$;
CREATE FUNCTION obrigacoes51.vinculos_leitura(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE c public.contratos%ROWTYPE;
BEGIN
 IF uid IS NULL OR uid<=0 OR cid IS NULL OR cid<=0 THEN RAISE EXCEPTION '51 owner/contrato inválidos' USING ERRCODE='22023';END IF;
 SELECT * INTO c FROM public.contratos WHERE id=cid LIMIT 1;
 IF NOT FOUND OR c.user_id IS DISTINCT FROM uid THEN RAISE EXCEPTION '51 registro indisponível' USING ERRCODE='42501';END IF;
 IF c.conta_caixa_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=c.cliente_id AND user_id=uid LIMIT 1)
 OR NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=c.conta_caixa_id AND user_id=uid LIMIT 1)
 OR (c.koletor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.koletores WHERE id=c.koletor_id AND user_id=uid LIMIT 1))
 OR EXISTS(SELECT 1 FROM public.parcelas p WHERE p.contrato_id=cid AND (p.user_id IS DISTINCT FROM uid OR p.cliente_id IS DISTINCT FROM c.cliente_id OR p.koletor_id IS DISTINCT FROM c.koletor_id OR p.conta_caixa_id IS DISTINCT FROM c.conta_caixa_id) LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.contrato_historico WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid::text LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.transacoes_caixa t WHERE (t.conta_caixa_id=c.conta_caixa_id OR t.contrato_id=cid OR t.parcela_id IN(SELECT id FROM public.parcelas WHERE contrato_id=cid)) AND (t.user_id IS DISTINCT FROM uid OR NOT EXISTS(SELECT 1 FROM public.contas_caixa a WHERE a.id=t.conta_caixa_id AND a.user_id=uid LIMIT 1) OR (t.contrato_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contratos co WHERE co.id=t.contrato_id AND co.user_id=uid LIMIT 1)) OR (t.parcela_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parcelas p JOIN public.contratos co ON co.id=p.contrato_id WHERE p.id=t.parcela_id AND p.user_id=uid AND co.user_id=uid AND t.contrato_id=co.id LIMIT 1))) LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.adicionais WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.encerramentos WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 THEN RAISE EXCEPTION '51 vínculos próprios completos obrigatórios; sem saneamento' USING ERRCODE='42501';END IF;
END $$;
CREATE FUNCTION obrigacoes51.travar_leitura(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE aid integer;
BEGIN
 PERFORM obrigacoes51.vinculos_leitura(uid,cid);SELECT conta_caixa_id INTO STRICT aid FROM public.contratos WHERE id=cid LIMIT 1;PERFORM public.legados_travar(uid,cid,aid);PERFORM obrigacoes51.vinculos_leitura(uid,cid);
END $$;
CREATE FUNCTION obrigacoes51.vinculos(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE c public.contratos%ROWTYPE;
BEGIN
 IF uid IS NULL OR uid<=0 OR cid IS NULL OR cid<=0 THEN RAISE EXCEPTION '51 owner/contrato inválidos' USING ERRCODE='22023';END IF;
 SELECT * INTO c FROM public.contratos WHERE id=cid LIMIT 1;
 IF NOT FOUND OR c.user_id IS DISTINCT FROM uid THEN RAISE EXCEPTION '51 registro indisponível' USING ERRCODE='42501';END IF;
 IF c.modalidade='cheque' THEN RAISE EXCEPTION '51 Cheques fora do escopo' USING ERRCODE='0A000';END IF;
 IF c.conta_caixa_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=c.cliente_id AND user_id=uid LIMIT 1)
 OR NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=c.conta_caixa_id AND user_id=uid LIMIT 1)
 OR (c.koletor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.koletores WHERE id=c.koletor_id AND user_id=uid LIMIT 1))
 OR EXISTS(SELECT 1 FROM public.parcelas p WHERE p.contrato_id=cid AND (p.user_id IS DISTINCT FROM uid OR p.cliente_id IS DISTINCT FROM c.cliente_id OR p.koletor_id IS DISTINCT FROM c.koletor_id OR p.conta_caixa_id IS DISTINCT FROM c.conta_caixa_id) LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.contrato_historico WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid::text LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.transacoes_caixa t WHERE (t.conta_caixa_id=c.conta_caixa_id OR t.contrato_id=cid OR t.parcela_id IN(SELECT id FROM public.parcelas WHERE contrato_id=cid)) AND (t.user_id IS DISTINCT FROM uid OR NOT EXISTS(SELECT 1 FROM public.contas_caixa a WHERE a.id=t.conta_caixa_id AND a.user_id=uid LIMIT 1) OR (t.contrato_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contratos co WHERE co.id=t.contrato_id AND co.user_id=uid LIMIT 1)) OR (t.parcela_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.parcelas p JOIN public.contratos co ON co.id=p.contrato_id WHERE p.id=t.parcela_id AND p.user_id=uid AND co.user_id=uid AND t.contrato_id=co.id LIMIT 1))) LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 OR EXISTS(SELECT 1 FROM obrigacoes51.adicionais WHERE contrato_id=cid AND user_id IS DISTINCT FROM uid LIMIT 1)
 THEN RAISE EXCEPTION '51 vínculos próprios completos obrigatórios; sem saneamento' USING ERRCODE='42501';END IF;
END $$;
CREATE FUNCTION obrigacoes51.travar(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE aid integer;
BEGIN
 PERFORM obrigacoes51.vinculos(uid,cid);SELECT conta_caixa_id INTO STRICT aid FROM public.contratos WHERE id=cid LIMIT 1;PERFORM public.legados_travar(uid,cid,aid);PERFORM obrigacoes51.vinculos(uid,cid);
END $$;
CREATE FUNCTION obrigacoes51.origem(uid integer,cid integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE n integer;
BEGIN
 n:=(SELECT count(*) FROM public.multimodal_origens WHERE contrato_id=cid)+(SELECT count(*) FROM public.emprestimos_rpc_origens WHERE contrato_id=cid)+(SELECT count(*) FROM public.legados_estados WHERE contrato_id=cid);
 IF n>1 THEN RAISE EXCEPTION '51 origem dupla/ambígua' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.multimodal_origens WHERE contrato_id=cid LIMIT 1) THEN PERFORM public.multimodal_validar(uid,cid);RETURN 'multimodal35';END IF;
 IF EXISTS(SELECT 1 FROM public.emprestimos_rpc_origens WHERE contrato_id=cid LIMIT 1) THEN PERFORM public.ciclo_validar(uid,cid);RETURN 'prospectivo21';END IF;
 IF EXISTS(SELECT 1 FROM private47.cadeia WHERE cid IN(origem_id,sucessor_id) LIMIT 1) OR EXISTS(SELECT 1 FROM public.reparcelamento43_cadeia WHERE cid IN(origem_id,sucessor_id) LIMIT 1) THEN RAISE EXCEPTION '51 atuar no sucessor atual requer protocolo específico' USING ERRCODE='0A000';END IF;
 RETURN 'legado';
END $$;
CREATE FUNCTION obrigacoes51.base(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE source text;
BEGIN
 PERFORM obrigacoes51.vinculos(uid,cid);source:=obrigacoes51.origem(uid,cid);
 RETURN jsonb_build_object('origemTipo',source,'financeiro',CASE source WHEN 'prospectivo21' THEN public.ciclo_snapshot(cid) ELSE public.multimodal_snapshot(cid) END,
 'cancelamentos',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY parcela_id) FROM obrigacoes51.cancelamentos x WHERE contrato_id=cid),'[]'::jsonb),'encerramento',(SELECT to_jsonb(x) FROM obrigacoes51.encerramentos x WHERE contrato_id=cid),
 'arquivos',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY parcela_id NULLS FIRST) FROM obrigacoes51.arquivos x WHERE contrato_id=cid),'[]'::jsonb),'adicionais',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY numero) FROM obrigacoes51.adicionais x WHERE contrato_id=cid),'[]'::jsonb),
 'conta',(SELECT to_jsonb(a) FROM public.contas_caixa a JOIN public.contratos c ON c.conta_caixa_id=a.id WHERE c.id=cid),'livroConta',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.id),'[]'::jsonb) FROM public.transacoes_caixa t JOIN public.contratos c ON c.conta_caixa_id=t.conta_caixa_id WHERE c.id=cid));
END $$;
CREATE FUNCTION obrigacoes51.registrada(p jsonb) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE v numeric; paid numeric; residual numeric;
BEGIN
 IF p->>'status' IN('paga','pago','cancelada','cancelado','renovada') THEN RETURN 0;END IF;
 IF p->>'status' NOT IN('pendente','atrasada','atrasado','vencendo_hoje','parcial') OR p->'valor' IS NULL OR p->'valor_original' IS NULL OR p->'valor_pago' IS NULL OR p->'saldo_residual' IS NULL THEN RAISE EXCEPTION '51 obrigação registrada ambígua' USING ERRCODE='23514';END IF;
 v:=(p->>'valor')::numeric;paid:=(p->>'valor_pago')::numeric;residual:=(p->>'saldo_residual')::numeric;
 IF NOT public.multimodal_moeda(v) OR NOT public.multimodal_moeda(paid) OR NOT public.multimodal_moeda(residual) OR v<=0 OR p->>'valor_original' IS NULL OR NOT public.multimodal_moeda((p->>'valor_original')::numeric) THEN RAISE EXCEPTION '51 valores registrados inválidos' USING ERRCODE='23514';END IF;
 IF p->>'status'='parcial' THEN
 IF paid<=0 OR residual<=0 OR (p->>'valor_original')::numeric+(p->>'valor_multa')::numeric+(p->>'multa_diaria_usada')::numeric-paid IS DISTINCT FROM residual OR (p->>'valor_desconto')::numeric IS DISTINCT FROM 0::numeric THEN RAISE EXCEPTION '51 residual parcial ambíguo' USING ERRCODE='23514';END IF;RETURN residual;
 END IF;
 IF v IS DISTINCT FROM (p->>'valor_original')::numeric OR paid IS DISTINCT FROM 0::numeric OR residual IS DISTINCT FROM 0::numeric OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION '51 aliases/baixa registrada ambíguos' USING ERRCODE='23514';END IF;RETURN v;
END $$;
-- Read-only provenance dispatch: support is not permission to create a new action51.
CREATE FUNCTION obrigacoes51.validar_leitura(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE n integer; ch record;
BEGIN
 n:=(SELECT count(*) FROM public.multimodal_origens WHERE contrato_id=cid)+(SELECT count(*) FROM public.emprestimos_rpc_origens WHERE contrato_id=cid)+(SELECT count(*) FROM public.legados_estados WHERE contrato_id=cid);
 IF n>1 THEN RAISE EXCEPTION '51 origem dupla/ambígua' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM private47.cadeia WHERE cid IN(origem_id,sucessor_id) LIMIT 1) THEN
 PERFORM private47.validar(uid,cid);RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM public.reparcelamento43_cadeia WHERE cid IN(origem_id,sucessor_id) LIMIT 1) THEN
 PERFORM public.reparcelamento43_validar(uid,cid);
 -- Prove each existing successor with its original snapshot/receipt protocol.
 -- Historical intermediate origins use their immutable43 snapshot, never a new writer51.
 FOR ch IN SELECT c.sucessor_id FROM public.reparcelamento43_cadeia c WHERE c.raiz_id=(SELECT raiz_id FROM public.reparcelamento43_cadeia WHERE cid IN(origem_id,sucessor_id) ORDER BY origem_id LIMIT 1) ORDER BY c.sucessor_id LOOP
 PERFORM public.reparcelamento43_validar(uid,ch.sucessor_id);
 IF NOT EXISTS(SELECT 1 FROM public.reparcelamento43_cadeia WHERE origem_id=ch.sucessor_id LIMIT 1) THEN PERFORM public.reparcelamento43_validar_recebimento(uid,ch.sucessor_id);END IF;
 END LOOP;RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM public.multimodal_origens WHERE contrato_id=cid LIMIT 1) THEN PERFORM public.multimodal_validar(uid,cid);RETURN;END IF;
 IF EXISTS(SELECT 1 FROM public.emprestimos_rpc_origens WHERE contrato_id=cid LIMIT 1) THEN PERFORM public.ciclo_validar(uid,cid);RETURN;END IF;
 -- Unregistered legacy is read as registered, not adopted/repaired; registrada retains its ambiguity refusals.
 IF EXISTS(SELECT 1 FROM public.legados_estados e WHERE e.contrato_id=cid AND (e.user_id IS DISTINCT FROM uid OR e.snapshot IS DISTINCT FROM public.legados_snapshot(cid)) LIMIT 1) THEN RAISE EXCEPTION '51 prova legada divergente' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION obrigacoes51.eventos_leitura(uid integer,cid integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE op obrigacoes51.operacoes%ROWTYPE; ev record; p jsonb; a obrigacoes51.adicionais%ROWTYPE; mop public.multimodal_operacoes%ROWTYPE;
BEGIN
 FOR op IN SELECT x.* FROM obrigacoes51.operacoes x WHERE x.contrato_id=cid ORDER BY x.created_at,x.id LOOP
 IF op.user_id IS DISTINCT FROM uid OR op.request IS DISTINCT FROM obrigacoes51.request(op.request) OR op.request->>'contratoId' IS DISTINCT FROM cid::text OR op.hash_request IS DISTINCT FROM obrigacoes51.hash(op.request)
 OR op.resultado IS NULL OR op.depois IS NULL OR op.concluida_em IS NULL OR op.hash_resultado IS DISTINCT FROM obrigacoes51.hash(op.resultado)
 OR op.resultado IS DISTINCT FROM obrigacoes51.fechar(uid,op.chave,op.request,op.id,op.resultado->'resultado')
 OR op.resultado->'resultado'->>'operationId' IS DISTINCT FROM op.id::text OR op.resultado->'resultado'->>'contratoId' IS DISTINCT FROM cid::text
 OR op.resultado->'resultado'->>'acao' IS DISTINCT FROM op.request->'proposta'->>'acao'
 OR op.request->>'estadoHash' IS DISTINCT FROM obrigacoes51.hash(jsonb_build_object('base',op.antes,'dia',obrigacoes51.dia(op.request->>'dataCalculo')))
 THEN RAISE EXCEPTION '51 evento sem closure exata' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR ev IN SELECT x.*,to_jsonb(x) row51 FROM obrigacoes51.cancelamentos x WHERE x.contrato_id=cid ORDER BY x.parcela_id LOOP
 SELECT * INTO STRICT op FROM obrigacoes51.operacoes WHERE id=ev.operacao_id LIMIT 1;
 SELECT to_jsonb(x) INTO STRICT p FROM public.parcelas x WHERE id=ev.parcela_id AND contrato_id=cid LIMIT 1;
 IF ev.user_id IS DISTINCT FROM uid OR op.user_id IS DISTINCT FROM uid OR op.contrato_id IS DISTINCT FROM cid OR op.request->'proposta'->>'acao' IS DISTINCT FROM 'cancelar'
 OR NOT(op.resultado->'resultado'->'idsAfetados' @> jsonb_build_array(ev.parcela_id))
 OR NOT(op.depois->'cancelamentos' @> jsonb_build_array(ev.row51))
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(op.antes->'financeiro'->'parcelas') j WHERE j=p LIMIT 1)
 OR ev.status_original IS DISTINCT FROM p->>'status' OR ev.status_original NOT IN('pendente','atrasada','atrasado','vencendo_hoje','parcial')
 OR ev.valor_pago_preservado IS DISTINCT FROM (p->>'valor_pago')::numeric OR ev.obrigacao_registrada IS DISTINCT FROM obrigacoes51.registrada(p)
 THEN RAISE EXCEPTION '51 renúncia sem prova registrada exata' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR ev IN SELECT x.*,to_jsonb(x) row51 FROM obrigacoes51.encerramentos x WHERE x.contrato_id=cid LOOP
 SELECT * INTO STRICT op FROM obrigacoes51.operacoes WHERE id=ev.operacao_id LIMIT 1;
 IF ev.user_id IS DISTINCT FROM uid OR op.user_id IS DISTINCT FROM uid OR op.contrato_id IS DISTINCT FROM cid
 OR op.request->'proposta' IS DISTINCT FROM jsonb_build_object('acao','cancelar','alvo',jsonb_build_object('tipo','contrato'),'reconhecoSemEstorno',true)
 OR op.depois->'encerramento' IS DISTINCT FROM ev.row51 OR NOT EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE operacao_id=op.id AND contrato_id=cid AND user_id=uid LIMIT 1)
 THEN RAISE EXCEPTION '51 encerramento sem renúncia comprovada' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR ev IN SELECT x.*,to_jsonb(x) row51 FROM obrigacoes51.arquivos x WHERE x.contrato_id=cid LOOP
 SELECT * INTO STRICT op FROM obrigacoes51.operacoes WHERE id=ev.operacao_id LIMIT 1;
 IF ev.user_id IS DISTINCT FROM uid OR op.user_id IS DISTINCT FROM uid OR op.contrato_id IS DISTINCT FROM cid
 OR op.request->'proposta' IS DISTINCT FROM jsonb_build_object('acao','arquivar','alvo',CASE WHEN ev.parcela_id IS NULL THEN jsonb_build_object('tipo','contrato') ELSE jsonb_build_object('tipo','parcela','parcelaId',ev.parcela_id) END)
 OR NOT(op.depois->'arquivos' @> jsonb_build_array(ev.row51))
 THEN RAISE EXCEPTION '51 arquivo sem prova exata' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR a IN SELECT x.* FROM obrigacoes51.adicionais x WHERE x.contrato_id=cid ORDER BY x.parcela_id LOOP
 SELECT * INTO STRICT mop FROM public.multimodal_operacoes WHERE id=a.operacao48 LIMIT 1;
 IF a.user_id IS DISTINCT FROM uid OR a.hash_linha IS DISTINCT FROM obrigacoes51.hash(a.linha_inicial) OR a.linha_inicial->>'id' IS DISTINCT FROM a.parcela_id::text OR a.linha_inicial->>'contrato_id' IS DISTINCT FROM cid::text
 OR mop.user_id IS DISTINCT FROM uid OR mop.family IS DISTINCT FROM 'multimodal_manutencao48' OR mop.resultado IS NULL OR mop.hash_payload IS DISTINCT FROM obrigacoes51.hash(mop.payload)
 OR mop.request->'alteracao'->>'acao' IS DISTINCT FROM 'adicionar' OR (mop.request->'alteracao'->>'valor')::numeric IS DISTINCT FROM a.valor
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(mop.auditoria->'depois'->'parcelas') j WHERE j=a.linha_inicial LIMIT 1)
 THEN RAISE EXCEPTION '51 adicional sem testemunho exato' USING ERRCODE='23514';END IF;
 END LOOP;
END $$;
CREATE FUNCTION obrigacoes51.moeda_leitura(v numeric) RETURNS boolean LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT v IS NOT NULL AND v::text NOT IN('NaN','Infinity','-Infinity') AND v=round(v,2) AND v BETWEEN 0 AND 9999999999999.99;
$$;
CREATE FUNCTION obrigacoes51.registrada_leitura(p jsonb) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE v numeric; paid numeric; residual numeric;
BEGIN
 IF p->>'status' IN('paga','pago','cancelada','cancelado','renovada') THEN RETURN 0;END IF;
 IF p->>'status' NOT IN('pendente','atrasada','atrasado','vencendo_hoje','parcial') OR p->'valor' IS NULL OR p->'valor_original' IS NULL OR p->'valor_pago' IS NULL OR p->'saldo_residual' IS NULL THEN RAISE EXCEPTION '51 obrigação registrada ambígua' USING ERRCODE='23514';END IF;
 v:=(p->>'valor')::numeric;paid:=(p->>'valor_pago')::numeric;residual:=(p->>'saldo_residual')::numeric;
 IF NOT obrigacoes51.moeda_leitura(v) OR NOT obrigacoes51.moeda_leitura(paid) OR NOT obrigacoes51.moeda_leitura(residual) OR v<=0 OR p->>'valor_original' IS NULL OR NOT obrigacoes51.moeda_leitura((p->>'valor_original')::numeric) THEN RAISE EXCEPTION '51 valores registrados inválidos' USING ERRCODE='23514';END IF;
 IF p->>'status'='parcial' THEN
 IF paid<=0 OR residual<=0 OR (p->>'valor_original')::numeric+(p->>'valor_multa')::numeric+(p->>'multa_diaria_usada')::numeric-paid IS DISTINCT FROM residual OR (p->>'valor_desconto')::numeric IS DISTINCT FROM 0::numeric THEN RAISE EXCEPTION '51 residual parcial ambíguo' USING ERRCODE='23514';END IF;RETURN residual;
 END IF;
 IF v IS DISTINCT FROM (p->>'valor_original')::numeric OR paid IS DISTINCT FROM 0::numeric OR residual IS DISTINCT FROM 0::numeric OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION '51 aliases/baixa registrada ambíguos' USING ERRCODE='23514';END IF;RETURN v;
END $$;
CREATE FUNCTION obrigacoes51.estado(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE p jsonb; rows jsonb:='[]'; v numeric; a numeric; total numeric:=0; open_count integer:=0; canceled boolean:=false; st text;
BEGIN
 PERFORM obrigacoes51.verificar();PERFORM obrigacoes51.travar_leitura(uid,cid);PERFORM obrigacoes51.validar_leitura(uid,cid);PERFORM obrigacoes51.eventos_leitura(uid,cid);
 canceled:=EXISTS(SELECT 1 FROM obrigacoes51.encerramentos WHERE contrato_id=cid AND user_id=uid LIMIT 1);
 FOR p IN SELECT to_jsonb(x) FROM public.parcelas x WHERE contrato_id=cid ORDER BY id LOOP
 v:=obrigacoes51.registrada_leitura(p);SELECT valor INTO a FROM obrigacoes51.adicionais WHERE parcela_id=(p->>'id')::int LIMIT 1;a:=coalesce(a,0);total:=total+a;
 IF p->>'status' IN('paga','pago') THEN v:=0;st:='paga';
 ELSIF p->>'status'='renovada' THEN v:=0;st:='transferida';
 ELSIF EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=(p->>'id')::int AND user_id=uid LIMIT 1) OR EXISTS(SELECT 1 FROM obrigacoes51.encerramentos WHERE contrato_id=cid AND user_id=uid LIMIT 1) OR p->>'status' IN('cancelada','cancelado') THEN v:=0;st:='cancelada';canceled:=true;
 ELSE st:='aberta';open_count:=open_count+1;END IF;
 rows:=rows||jsonb_build_array(jsonb_build_object('parcelaId',(p->>'id')::int,'statusFinanceiroOriginal',p->>'status','statusObrigacao',st,'obrigacaoAtual',v::numeric(15,2)::text,'componenteAdicional',a::numeric(15,2)::text,'arquivada',EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid AND (parcela_id IS NULL OR parcela_id=(p->>'id')::int) LIMIT 1)));
 END LOOP;
 RETURN jsonb_build_object('versao','obrigacoes51_v1','userId',uid,'contratoId',cid,'statusObrigacao',CASE WHEN open_count>0 THEN 'ativo' WHEN canceled THEN 'encerrado_por_cancelamento' ELSE 'quitado' END,'arquivado',EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid AND parcela_id IS NULL LIMIT 1),'obrigacaoAdicional',total::numeric(15,2)::text,'parcelas',rows);
END $$;
CREATE FUNCTION obrigacoes51.plano(s jsonb,v jsonb,instante timestamptz,nova jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE c jsonb:=s->'contrato';p jsonb;np jsonb;ps jsonb:='[]';n integer:=jsonb_array_length(s->'parcelas');i integer:=0;changed integer:=0;pid integer;amount numeric;share numeric;total numeric:=0;today date:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;d date;prev date;nextd date;firstd date;lastd date;action text;
BEGIN
 v:=obrigacoes51.proposta(v);action:=v->>'acao';
 IF action NOT IN('adicionar','editar') OR c->>'status' IS DISTINCT FROM 'ativo' OR c->>'modalidade' IS DISTINCT FROM 'mensal' OR c->>'tipo_taxa' IS DISTINCT FROM 'mensal' OR n NOT BETWEEN 1 AND 60 OR c->'contrato_origem_id' IS DISTINCT FROM 'null'::jsonb OR c->>'num_parcelas' IS DISTINCT FROM n::text OR c->>'numero_parcelas' IS DISTINCT FROM n::text THEN RAISE EXCEPTION '51 edição/inclusão requer contrato mensal ativo íntegro' USING ERRCODE='0A000';END IF;
 IF action='adicionar' THEN
 IF n>=60 THEN RAISE EXCEPTION '51 máximo 60 parcelas' USING ERRCODE='22023';END IF;
 amount:=obrigacoes51.dinheiro(v->>'valor');d:=obrigacoes51.dia(v->>'dataVencimento');firstd:=(c->>'data_vencimento_primeira')::date;
 IF firstd IS NULL OR extract(day FROM firstd)>28 OR d<=today OR d IS DISTINCT FROM public.multimodal_data(firstd,'mensal',n) THEN RAISE EXCEPTION '51 inclusão: data informada deve ser próximo mês explícito ancorado1..28' USING ERRCODE='22023';END IF;
 END IF;
 IF action='editar' THEN
 pid:=obrigacoes51.id(v->'parcelaId');IF EXISTS(SELECT 1 FROM obrigacoes51.adicionais WHERE parcela_id=pid LIMIT 1) THEN RAISE EXCEPTION '51 editar componente adicional exige regra própria; não virar principal/juros' USING ERRCODE='0A000';END IF;
 SELECT (j->>'data_vencimento')::date INTO prev FROM jsonb_array_elements(s->'parcelas') j WHERE (j->>'numero')::int<(SELECT (x->>'numero')::int FROM jsonb_array_elements(s->'parcelas') x WHERE (x->>'id')::int=pid) ORDER BY (j->>'numero')::int DESC LIMIT 1;
 SELECT (j->>'data_vencimento')::date INTO nextd FROM jsonb_array_elements(s->'parcelas') j WHERE (j->>'numero')::int>(SELECT (x->>'numero')::int FROM jsonb_array_elements(s->'parcelas') x WHERE (x->>'id')::int=pid) ORDER BY (j->>'numero')::int LIMIT 1;
 END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int LOOP
 i:=i+1;np:=p;
 IF p->>'numero' IS DISTINCT FROM i::text OR p->>'numero_parcela' IS DISTINCT FROM i::text THEN RAISE EXCEPTION '51 sequência original divergente' USING ERRCODE='23514';END IF;
 IF action='adicionar' OR (p->>'id')::int=pid THEN
 IF p->>'status' IS DISTINCT FROM 'pendente' OR (p->>'data_vencimento')::date<=today OR (p->>'valor_pago')::numeric IS DISTINCT FROM 0::numeric OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb OR (p->>'saldo_residual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'valor_multa')::numeric IS DISTINCT FROM 0::numeric OR (p->>'valor_desconto')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_manual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_diaria_usada')::numeric IS DISTINCT FROM 0::numeric OR (p->>'valor')::numeric IS DISTINCT FROM (p->>'valor_original')::numeric THEN RAISE EXCEPTION '51 alvo somente integralmente aberto futuro sem baixa/encargos' USING ERRCODE='23514';END IF;
 IF action='adicionar' AND (p->>'data_vencimento')::date IS DISTINCT FROM public.multimodal_data(firstd,'mensal',i-1) THEN RAISE EXCEPTION '51 append requer calendário mensal; exceção individual não é sanada' USING ERRCODE='23514';END IF;
 IF action='editar' THEN
 share:=(p->>'valor_original')::numeric-(p->>'valor_juros')::numeric;amount:=CASE WHEN v ? 'novoValor' THEN obrigacoes51.dinheiro(v->>'novoValor') ELSE (p->>'valor')::numeric END;d:=CASE WHEN v ? 'novaDataVencimento' THEN obrigacoes51.dia(v->>'novaDataVencimento') ELSE (p->>'data_vencimento')::date END;
 IF share<=0 OR amount<share OR d<=today OR d<(c->>'data_inicio')::date OR (prev IS NOT NULL AND d<=prev) OR (nextd IS NOT NULL AND d>=nextd) THEN RAISE EXCEPTION '51 preservar principal e DATE estrita entre vizinhos reais' USING ERRCODE='22023';END IF;
 IF amount IS DISTINCT FROM (p->>'valor')::numeric OR d IS DISTINCT FROM (p->>'data_vencimento')::date THEN np:=p||jsonb_build_object('valor',amount,'valor_original',amount,'valor_juros',amount-share,'data_vencimento',d,'updatedAt',instante);changed:=1;END IF;
 END IF;
 END IF;
 total:=total+(np->>'valor')::numeric;ps:=ps||jsonb_build_array(np);
 END LOOP;
 IF action='adicionar' THEN
 IF nova IS NOT NULL THEN
 np:=nova||jsonb_build_object('user_id',(c->>'user_id')::int,'contrato_id',(c->>'id')::int,'cliente_id',(c->>'cliente_id')::int,'koletor_id',(c->>'koletor_id')::int,'conta_caixa_id',(c->>'conta_caixa_id')::int,'numero',n+1,'numero_parcela',n+1,'valor',amount,'valor_original',amount,'valor_juros',0,'valor_pago',0,'valor_multa',0,'valor_desconto',0,'saldo_residual',0,'multa_manual',0,'multa_diaria_usada',0,'data_vencimento',d,'data_pagamento',NULL,'status','pendente','createdAt',instante,'updatedAt',instante);
 ps:=ps||jsonb_build_array(np);END IF;
 total:=total+amount;n:=n+1;changed:=1;c:=c||jsonb_build_object('num_parcelas',n,'numero_parcelas',n,'data_vencimento',d);
 ELSE
 IF changed=0 THEN RAISE EXCEPTION '51 sem delta real' USING ERRCODE='22023';END IF;
 SELECT (j->>'data_vencimento')::date INTO firstd FROM jsonb_array_elements(ps) j ORDER BY (j->>'numero')::int LIMIT 1;SELECT (j->>'data_vencimento')::date INTO lastd FROM jsonb_array_elements(ps) j ORDER BY (j->>'numero')::int DESC LIMIT 1;
 c:=c||jsonb_build_object('data_vencimento_primeira',firstd,'dia_vencimento',extract(day FROM firstd)::int,'data_vencimento',lastd);
 END IF;
 IF NOT public.multimodal_moeda(total) THEN RAISE EXCEPTION '51 overflow nominal/histórico' USING ERRCODE='22023';END IF;
 IF action='adicionar' OR total IS DISTINCT FROM (c->>'total_contrato')::numeric THEN c:=c||jsonb_build_object('total_contrato',total,'valor_parcela',round(total/n,2));END IF;
 c:=c||jsonb_build_object('updatedAt',instante);
 RETURN jsonb_build_object('contrato',c,'parcelas',(SELECT jsonb_agg(j ORDER BY (j->>'id')::int) FROM jsonb_array_elements(ps) j),'totalContrato',total::numeric(12,2)::text,'jurosTotal',(SELECT sum((j->>'valor_juros')::numeric)::numeric(12,2)::text FROM jsonb_array_elements(ps) j),'obrigacaoCancelada','0.00','alteradas',1,'regra','obrigacoes51_v1');
END $$;
CREATE FUNCTION obrigacoes51.validar_mensal(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE s jsonb;c jsonb;o public.multimodal_origens%ROWTYPE;creation public.multimodal_operacoes%ROWTYPE;p jsonb;n integer;
BEGIN
 s:=public.multimodal_validar(uid,cid);c:=s->'contrato';SELECT * INTO STRICT o FROM public.multimodal_origens WHERE contrato_id=cid AND user_id=uid LIMIT 1;SELECT * INTO STRICT creation FROM public.multimodal_operacoes WHERE id=o.operacao_id LIMIT 1;
 n:=o.numero_inicial+(SELECT count(*) FROM obrigacoes51.adicionais WHERE contrato_id=cid AND user_id=uid);
 IF creation.family IS DISTINCT FROM 'multimodal_criar' OR creation.resultado IS NULL OR creation.auditoria->'payload' IS DISTINCT FROM creation.payload OR creation.hash_payload IS DISTINCT FROM obrigacoes51.hash(creation.payload) OR creation.auditoria->'depois'->'origem' IS DISTINCT FROM s->'origem' OR c->>'status' IS DISTINCT FROM 'ativo' OR c->>'modalidade' IS DISTINCT FROM 'mensal' OR c->>'tipo_taxa' IS DISTINCT FROM 'mensal' OR jsonb_array_length(s->'parcelas') IS DISTINCT FROM n OR n NOT BETWEEN 1 AND 60 OR (c->>'num_parcelas')::int IS DISTINCT FROM n OR (c->>'numero_parcelas')::int IS DISTINCT FROM n OR s->'renovacoes' IS DISTINCT FROM '[]'::jsonb OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid LIMIT 1) THEN RAISE EXCEPTION '51 mensal35 genuíno/inclusões próprias/contagem íntegra obrigatórios' USING ERRCODE='23514';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(creation.auditoria->'depois'->'parcelas') op WHERE op->'id'=p->'id' AND op->'numero'=p->'numero' AND op->'numero_parcela'=p->'numero_parcela') AND NOT EXISTS(SELECT 1 FROM obrigacoes51.adicionais a JOIN public.multimodal_operacoes op ON op.id=a.operacao48 WHERE a.user_id=uid AND a.contrato_id=cid AND a.parcela_id=(p->>'id')::int AND a.numero=(p->>'numero')::int AND a.numero=(p->>'numero_parcela')::int AND op.user_id=uid AND op.family='multimodal_manutencao48' AND op.resultado IS NOT NULL AND op.request->'alteracao'->>'acao'='adicionar' AND a.hash_linha=obrigacoes51.hash(a.linha_inicial) LIMIT 1) THEN RAISE EXCEPTION '51 linha extra não provada/identidade alterada' USING ERRCODE='23514';END IF;
 END LOOP;RETURN s;
END $$;
CREATE FUNCTION obrigacoes51.replay21(uid integer,cid integer,target jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE origin public.emprestimos_rpc_origens%ROWTYPE;creation public.emprestimos_rpc_operacoes%ROWTYPE;ev record;pending manutencao44.operacoes%ROWTYPE;s jsonb;initial jsonb;before_s jsonb;after_s jsonb;expected jsonb;plan jsonb;p jsonb;ps jsonb;h jsonb;nc jsonb;stamp timestamptz;dates date[];n integer;applied integer:=0;total integer;seen text[]:='{}';candidates integer;
BEGIN
 SELECT * INTO STRICT origin FROM public.emprestimos_rpc_origens WHERE contrato_id=cid AND user_id=uid LIMIT 1;SELECT * INTO STRICT creation FROM public.emprestimos_rpc_operacoes WHERE id=origin.operacao_id AND user_id=uid LIMIT 1;
 initial:=jsonb_build_object('contrato',creation.auditoria->'contrato','parcelas',creation.auditoria->'parcelas','origem',to_jsonb(origin),
 'ledger',jsonb_build_array((SELECT to_jsonb(t) FROM public.transacoes_caixa t WHERE id=origin.transacao_caixa_id LIMIT 1)),
 'historico',jsonb_build_array((SELECT to_jsonb(hh) FROM public.contrato_historico hh WHERE id=(creation.auditoria->>'historicoId')::bigint LIMIT 1)));
 PERFORM obrigacoes51.validar44_base(uid,cid,initial);s:=initial;n:=jsonb_array_length(s->'parcelas');
 SELECT count(*) INTO total FROM (
 SELECT id::text tag FROM manutencao44.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL
 UNION ALL SELECT id::text FROM obrigacoes51.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL AND request->'proposta'->>'acao'='editar'
 ) e;
 IF total>1024 THEN RAISE EXCEPTION '51 cadeia21 excedeu limite fechado' USING ERRCODE='54000';END IF;
 WHILE applied<total LOOP
 SELECT count(*) INTO candidates FROM (
 SELECT id::text tag,antes FROM manutencao44.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL
 UNION ALL SELECT id::text,antes->'financeiro' FROM obrigacoes51.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL AND request->'proposta'->>'acao'='editar'
 ) e WHERE e.antes=s AND NOT(e.tag=ANY(seen));
 IF candidates<>1 THEN RAISE EXCEPTION '51 cadeia21 ausente/ramificada/inconsistente' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT ev FROM (
 SELECT id::text tag,'44' kind,request,antes,depois,resultado,concluida_em,hash_payload hash_req FROM manutencao44.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL
 UNION ALL SELECT id::text,'51',request,antes->'financeiro',depois->'financeiro',resultado,concluida_em,hash_request FROM obrigacoes51.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL AND request->'proposta'->>'acao'='editar'
 ) e WHERE e.antes=s AND NOT(e.tag=ANY(seen)) LIMIT 1;
 after_s:=ev.depois;stamp:=(after_s->'contrato'->>'updatedAt')::timestamptz;expected:=s;h:=after_s->'historico'->jsonb_array_length(s->'historico');
 IF ev.hash_req IS DISTINCT FROM obrigacoes51.hash(ev.request) OR ev.concluida_em IS NULL OR stamp IS NULL OR ev.concluida_em<stamp OR h->>'contrato_id' IS DISTINCT FROM cid::text OR h->>'user_id' IS DISTINCT FROM uid::text OR (h->>'created_at')::timestamptz IS DISTINCT FROM stamp OR h->'valor_anterior' IS DISTINCT FROM 'null'::jsonb OR h->'valor_novo' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION '51 cadeia21 request/timestamp/histórico inválido' USING ERRCODE='23514';END IF;
 IF ev.kind='51' THEN
 IF ev.request IS DISTINCT FROM obrigacoes51.request(ev.request) OR ev.request->>'estadoHash' IS DISTINCT FROM obrigacoes51.hash(jsonb_build_object('base',(SELECT antes FROM obrigacoes51.operacoes WHERE id=ev.tag::uuid LIMIT 1),'dia',ev.request->>'dataCalculo')) OR ev.resultado->'request' IS DISTINCT FROM ev.request OR ev.resultado->'resultado'->>'operationId' IS DISTINCT FROM ev.tag OR h->>'tipo' IS DISTINCT FROM 'edicao_parcela' OR h->>'descricao' IS DISTINCT FROM 'Edição51 '||ev.tag||': '||(ev.request->>'motivo') THEN RAISE EXCEPTION '51 edição21 prova divergente' USING ERRCODE='23514';END IF;
 plan:=obrigacoes51.plano(s,ev.request->'proposta',stamp);expected:=jsonb_set(jsonb_set(expected,'{contrato}',plan->'contrato'),'{parcelas}',(SELECT jsonb_agg(j ORDER BY (j->>'numero')::int,(j->>'id')::int) FROM jsonb_array_elements(plan->'parcelas') j));
 ELSE
 SELECT array_agg(d::date ORDER BY ord) INTO dates FROM jsonb_array_elements_text(ev.request->'vencimentos') WITH ORDINALITY x(d,ord);PERFORM manutencao44.agenda(cid,dates,(s->'contrato'->>'data_inicio')::date,n);
 IF ev.request IS DISTINCT FROM manutencao44.request(cid,obrigacoes51.hash(s),dates,ev.request->>'motivo') OR h->>'tipo' IS DISTINCT FROM 'edicao_calendario' OR h->>'descricao' IS DISTINCT FROM 'Calendário auditado '||ev.tag||': '||(ev.request->>'motivo') THEN RAISE EXCEPTION '51 calendário21 prova divergente' USING ERRCODE='23514';END IF;
 ps:='[]';FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int,(value->>'id')::int LOOP ps:=ps||jsonb_build_array(p||jsonb_build_object('data_vencimento',dates[(p->>'numero')::int],'status',CASE WHEN dates[(p->>'numero')::int]<(stamp AT TIME ZONE 'America/Sao_Paulo')::date THEN 'atrasada' WHEN dates[(p->>'numero')::int]=(stamp AT TIME ZONE 'America/Sao_Paulo')::date THEN 'vencendo_hoje' ELSE 'pendente' END,'updatedAt',stamp));END LOOP;
 nc:=s->'contrato'||jsonb_build_object('data_vencimento_primeira',dates[1],'data_vencimento',dates[n],'dia_vencimento',extract(day FROM dates[1])::int,'updatedAt',stamp);expected:=jsonb_set(jsonb_set(expected,'{contrato}',nc),'{parcelas}',ps);
 END IF;
 expected:=jsonb_set(expected,'{historico}',s->'historico'||jsonb_build_array(h));IF expected IS DISTINCT FROM after_s THEN RAISE EXCEPTION '51 cadeia21 delta integral divergente' USING ERRCODE='23514';END IF;
 s:=after_s;seen:=array_append(seen,ev.tag);applied:=applied+1;
 END LOOP;
 -- Existing44 calls its validator after its DML/readback, before closing op44. Prove that in-progress exact request too.
 IF s IS DISTINCT FROM target THEN
 SELECT * INTO pending FROM manutencao44.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NULL AND antes=s AND pg_xact_status(xmin::text::xid8)='in progress' LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION '51 cadeia21 terminal não corresponde estado físico' USING ERRCODE='23514';END IF;
 stamp:=(target->'contrato'->>'updatedAt')::timestamptz;SELECT array_agg(d::date ORDER BY ord) INTO dates FROM jsonb_array_elements_text(pending.request->'vencimentos') WITH ORDINALITY x(d,ord);PERFORM manutencao44.agenda(cid,dates,(s->'contrato'->>'data_inicio')::date,n);
 IF pending.request IS DISTINCT FROM manutencao44.request(cid,obrigacoes51.hash(s),dates,pending.request->>'motivo') THEN RAISE EXCEPTION '51 pendente44 exata inválida' USING ERRCODE='23514';END IF;
 ps:='[]';FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int,(value->>'id')::int LOOP ps:=ps||jsonb_build_array(p||jsonb_build_object('data_vencimento',dates[(p->>'numero')::int],'status',CASE WHEN dates[(p->>'numero')::int]<(stamp AT TIME ZONE 'America/Sao_Paulo')::date THEN 'atrasada' WHEN dates[(p->>'numero')::int]=(stamp AT TIME ZONE 'America/Sao_Paulo')::date THEN 'vencendo_hoje' ELSE 'pendente' END,'updatedAt',stamp));END LOOP;
 nc:=s->'contrato'||jsonb_build_object('data_vencimento_primeira',dates[1],'data_vencimento',dates[n],'dia_vencimento',extract(day FROM dates[1])::int,'updatedAt',stamp);h:=target->'historico'->jsonb_array_length(s->'historico');expected:=jsonb_set(jsonb_set(jsonb_set(s,'{contrato}',nc),'{parcelas}',ps),'{historico}',s->'historico'||jsonb_build_array(h));
 IF h->>'tipo' IS DISTINCT FROM 'edicao_calendario' OR h->>'descricao' IS DISTINCT FROM 'Calendário auditado '||pending.id::text||': '||(pending.request->>'motivo') OR h->>'user_id' IS DISTINCT FROM uid::text OR expected IS DISTINCT FROM target THEN RAISE EXCEPTION '51 pendente44 delta exato divergente' USING ERRCODE='23514';END IF;s:=target;
 END IF;RETURN s;
END $$;
ALTER TABLE private47.cadeia ADD COLUMN obrigacao_adicional numeric(15,2) NOT NULL DEFAULT 0 CHECK(obrigacao_adicional>=0);
ALTER TABLE private47.cadeia DROP CONSTRAINT cadeia_check;
ALTER TABLE private47.cadeia ADD CONSTRAINT cadeia_check CHECK(saldo_transferido=principal_original+juros_embutidos+obrigacao_adicional);
CREATE OR REPLACE FUNCTION manutencao48.proposta(v jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a text; s text;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' THEN RAISE EXCEPTION '48 invalid proposal' USING ERRCODE='22023'; END IF;
 a:=v->>'acao';
 IF a IN('adicionar','editar') THEN RETURN obrigacoes51.proposta(v); END IF;
 IF a='cancelar' AND v=jsonb_build_object('acao',a) THEN RETURN v; END IF;
 IF a='juros' AND v=jsonb_build_object('acao',a,'taxaJuros',v->>'taxaJuros') THEN
  s:=v->>'taxaJuros';
  IF s ~ '^(0|[1-9][0-9]{0,2})\.[0-9]{4}$' AND s::numeric<=100 AND round(s::numeric,2)=s::numeric THEN RETURN v; END IF;
 ELSIF a IN('valor','desconto') AND v=jsonb_build_object('acao',a,'parcelaId',v->'parcelaId','valor',v->>'valor') THEN
  s:=v->>'valor';
  IF jsonb_typeof(v->'parcelaId')='number' AND (v->>'parcelaId') ~ '^[1-9][0-9]{0,9}$' AND (v->>'parcelaId')::numeric<=2147483647
   AND s ~ '^(0|[1-9][0-9]{0,9})\.[0-9]{2}$' THEN RETURN v; END IF;
 END IF;
 RAISE EXCEPTION '48 exact proposal invalid; rate must fit physical NUMERIC(5,2)' USING ERRCODE='22023';
END $$;
CREATE OR REPLACE FUNCTION manutencao48.validar(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$ BEGIN RETURN obrigacoes51.validar_mensal(uid,cid); END $$;
CREATE OR REPLACE FUNCTION manutencao48.plano(s jsonb,v jsonb,instante timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE a text; p jsonb; np jsonb; ps jsonb:='[]'; c jsonb:=s->'contrato'; total numeric:=0; oldTotal numeric:=0; juros numeric:=0; base numeric:=0; jref numeric; n integer:=jsonb_array_length(s->'parcelas'); m integer:=0; i integer:=0; changed integer:=0; share numeric; j numeric; val numeric; discount numeric; cancelado numeric:=0; extra_ids integer[]:='{}'; initial_n integer; hoje date:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
 v:=manutencao48.proposta(v); a:=v->>'acao';
 IF a IN('adicionar','editar') THEN RETURN obrigacoes51.plano(s,v,instante); END IF;
 SELECT coalesce(array_agg(parcela_id),'{}'::int[]) INTO extra_ids FROM obrigacoes51.adicionais WHERE contrato_id=(c->>'id')::int;
 SELECT numero_inicial INTO initial_n FROM public.multimodal_origens WHERE contrato_id=(c->>'id')::int;
 IF a IN('valor','desconto') AND (v->>'parcelaId')::int=ANY(extra_ids) THEN RAISE EXCEPTION '51 componente adicional não é principal/juros' USING ERRCODE='0A000'; END IF;
 IF a='juros' THEN
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') LOOP
 IF p->>'status' IN('pendente','atrasada','vencendo_hoje','parcial') AND NOT((p->>'id')::int=ANY(extra_ids)) THEN
  IF p->>'status'<>'pendente' OR (p->>'valor_pago')::numeric<>0 OR p->'data_pagamento'<>'null'::jsonb OR (p->>'saldo_residual')::numeric<>0 OR (p->>'valor_desconto')::numeric<>0 OR (p->>'data_vencimento')::date<=hoje THEN RAISE EXCEPTION '48 repricing only wholly open future; paid rows stay byte-exact' USING ERRCODE='23514'; END IF;
  m:=m+1; base:=base+(p->>'valor_original')::numeric-(p->>'valor_juros')::numeric;
 END IF;
 END LOOP;
 IF m=0 OR (v->>'taxaJuros')::numeric=(c->>'taxa_juros')::numeric THEN RAISE EXCEPTION '48 rate unchanged or no future obligations' USING ERRCODE='22023'; END IF;
 juros:=round(base*(v->>'taxaJuros')::numeric/100*coalesce(initial_n,n),2); jref:=round(juros/m,2);
 END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int LOOP
 np:=p; share:=(p->>'valor_original')::numeric-(p->>'valor_juros')::numeric;
 oldTotal:=oldTotal+(p->>'valor')::numeric;
 IF a='cancelar' AND p->>'status' IN('pendente','atrasada','vencendo_hoje','parcial') THEN
  cancelado:=cancelado+CASE WHEN p->>'status'='parcial' THEN (p->>'saldo_residual')::numeric ELSE greatest(0,(p->>'valor')::numeric-(p->>'valor_pago')::numeric) END;
  np:=p||jsonb_build_object('status','cancelada','updatedAt',instante); changed:=changed+1;
 ELSIF a='juros' AND p->>'status'='pendente' AND NOT((p->>'id')::int=ANY(extra_ids)) THEN
  i:=i+1; j:=CASE WHEN i=m THEN juros-jref*(m-1) ELSE jref END; val:=share+j;
  IF (p->>'valor_multa')::numeric<>0 OR (p->>'multa_manual')::numeric<>0 OR (p->>'multa_diaria_usada')::numeric<>0 OR share<=0 OR j<0 OR NOT public.multimodal_moeda(val) THEN RAISE EXCEPTION '48 principal-preserving rate allocation unrepresentable' USING ERRCODE='23514'; END IF;
  np:=p||jsonb_build_object('valor',val,'valor_original',val,'valor_juros',j,'updatedAt',instante); changed:=changed+1;
 ELSIF a IN('valor','desconto') AND (p->>'id')::int=(v->>'parcelaId')::int THEN
  IF p->>'status'<>'pendente' OR (p->>'valor_pago')::numeric<>0 OR p->'data_pagamento'<>'null'::jsonb OR (p->>'saldo_residual')::numeric<>0 OR (p->>'data_vencimento')::date<=hoje
  OR (p->>'valor_multa')::numeric<>0 OR (p->>'multa_manual')::numeric<>0 OR (p->>'multa_diaria_usada')::numeric<>0 THEN RAISE EXCEPTION '48 only targeted wholly open future row; never rewrite receipt' USING ERRCODE='23514'; END IF;
  val:=(v->>'valor')::numeric;
  IF a='valor' THEN
   IF (p->>'valor_desconto')::numeric<>0 OR val<=0 OR val<share OR val=(p->>'valor')::numeric THEN RAISE EXCEPTION '48 amount must preserve principal, no discount, nonzero delta' USING ERRCODE='22023'; END IF;
   np:=p||jsonb_build_object('valor',val,'valor_original',val,'valor_juros',val-share,'updatedAt',instante);
  ELSE
   IF val>(p->>'valor_juros')::numeric+(p->>'valor_desconto')::numeric OR val=(p->>'valor_desconto')::numeric THEN RAISE EXCEPTION '48 discount must leave positive claim, nonzero delta' USING ERRCODE='22023'; END IF;
   discount:=(p->>'valor_desconto')::numeric;
   np:=p||jsonb_build_object('valor',(p->>'valor')::numeric+discount-val,'valor_original',(p->>'valor_original')::numeric+discount-val,'valor_juros',(p->>'valor_juros')::numeric+discount-val,'valor_desconto',val,'updatedAt',instante);
  END IF;
  changed:=changed+1;
 END IF;
 total:=total+(np->>'valor')::numeric; ps:=ps||jsonb_build_array(np);
 END LOOP;
 IF changed=0 OR NOT public.multimodal_moeda(total) THEN RAISE EXCEPTION '48 no target/change or unrepresentable total' USING ERRCODE='22023'; END IF;
 IF a='juros' THEN c:=c||jsonb_build_object('taxa_juros',(v->>'taxaJuros')::numeric); END IF;
 IF a IN('juros','valor','desconto') THEN c:=c||jsonb_build_object('total_contrato',total,'valor_parcela',round(total/n,2)); END IF;
 IF a='cancelar' THEN c:=c||jsonb_build_object('status','cancelado'); END IF;
 c:=c||jsonb_build_object('updatedAt',instante);
 RETURN jsonb_build_object('contrato',c,'parcelas',(SELECT jsonb_agg(jj ORDER BY (jj->>'id')::int) FROM jsonb_array_elements(ps) jj),'totalContrato',total::numeric(15,2)::text,'jurosTotal',(SELECT sum((jj->>'valor_juros')::numeric)::numeric(15,2)::text FROM jsonb_array_elements(ps) jj),'obrigacaoCancelada',cancelado::numeric(15,2)::text,'alteradas',changed,'regra','manutencao25_obrigacao_v1');
END $$;
CREATE OR REPLACE FUNCTION manutencao48.executar(uid integer,k uuid,cid integer,estado text,v jsonb,motivo text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE req jsonb; op public.multimodal_operacoes%ROWTYPE; antes jsonb; esperado jsonb; p jsonb; novo jsonb; h jsonb; r jsonb; plan jsonb; instante timestamptz; hoje date;
BEGIN
 PERFORM manutencao48.verificar(); req:=manutencao48.request(cid,estado,v,motivo);
 PERFORM public.multimodal_barreira(uid,'multimodal_manutencao48',k,false);
 IF EXISTS(SELECT 1 FROM public.multimodal_fences WHERE user_id=uid AND family='multimodal_manutencao48' AND chave=k) THEN
 IF EXISTS(SELECT 1 FROM public.multimodal_fences WHERE user_id=uid AND family='multimodal_manutencao48' AND chave=k AND request IS DISTINCT FROM req) THEN RAISE EXCEPTION '48 fenced payload divergence' USING ERRCODE='23505'; END IF;
 RAISE EXCEPTION '48 terminal fence' USING ERRCODE='23514'; END IF;
 op:=public.multimodal_reservar(uid,'multimodal_manutencao48',k,req);
 IF op.request IS DISTINCT FROM req THEN RAISE EXCEPTION '48 original request changed' USING ERRCODE='23505'; END IF;
 IF op.resultado IS NOT NULL THEN RETURN op.resultado||jsonb_build_object('repetida',true); END IF;
 PERFORM public.multimodal_travar(uid,cid); antes:=manutencao48.validar(uid,cid);
 IF encode(extensions.digest(antes::text,'sha256'),'hex') IS DISTINCT FROM estado THEN RAISE EXCEPTION '48 stale quote' USING ERRCODE='40001'; END IF;
 instante:=clock_timestamp(); hoje:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;
 IF v->>'acao'='adicionar' THEN
 novo:=public.multimodal_nova_linha('parcelas');plan:=obrigacoes51.plano(antes,v,instante,novo);
 SELECT value INTO STRICT novo FROM jsonb_array_elements(plan->'parcelas') WHERE value->'id'=novo->'id';
 PERFORM public.multimodal_escrever(op.id,'parcelas',NULL,novo);
 INSERT INTO obrigacoes51.adicionais VALUES(uid,cid,(novo->>'id')::int,op.id,(novo->>'numero')::int,(v->>'valor')::numeric,novo,obrigacoes51.hash(novo));
 ELSE plan:=manutencao48.plano(antes,v,instante); END IF; esperado:=antes;
 FOR p IN SELECT value FROM jsonb_array_elements(antes->'parcelas') ORDER BY (value->>'id')::int LOOP
 SELECT value INTO STRICT novo FROM jsonb_array_elements(plan->'parcelas') WHERE value->'id'=p->'id';
 IF novo IS DISTINCT FROM p THEN PERFORM public.multimodal_escrever(op.id,'parcelas',p,novo); END IF;
 END LOOP;
 esperado:=jsonb_set(esperado,'{parcelas}',plan->'parcelas');
 PERFORM public.multimodal_escrever(op.id,'contratos',antes->'contrato',plan->'contrato'); esperado:=jsonb_set(esperado,'{contrato}',plan->'contrato');
 h:=public.multimodal_nova_linha('contrato_historico')||jsonb_build_object('contrato_id',cid,'user_id',uid::text,'tipo','manutencao_'||(v->>'acao'),'descricao','Manutenção25 '||op.id::text||': '||motivo||CASE WHEN v->>'acao'='cancelar' THEN ' [baixa compensatória de obrigação; SEM estorno Caixa, capital não presumido devolvido]' ELSE '' END,'created_at',instante);
 PERFORM public.multimodal_escrever(op.id,'contrato_historico',NULL,h); esperado:=jsonb_set(esperado,'{historico}',esperado->'historico'||jsonb_build_array(h));
 IF (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date IS DISTINCT FROM hoje THEN RAISE EXCEPTION '48 civil day rollover' USING ERRCODE='40001'; END IF;
 r:=req||jsonb_build_object('success',true,'repetida',false,'operationId',op.id,'idempotencyKey',k,'regra','manutencao25_obrigacao_v1','totalContrato',plan->>'totalContrato','jurosTotal',plan->>'jurosTotal','obrigacaoCancelada',plan->>'obrigacaoCancelada');
 r:=public.multimodal_selar(op.id,cid,antes,esperado,r,jsonb_build_object('familia','multimodal_manutencao48','origemOperacao',antes->'origem'->>'operacao_id','predecessorEstadoHash',estado,'delta','future_claims+contract_summary+append_history; cancellation=obligation_writeoff_not_cash_reversal','compensacaoObrigacao',plan->>'obrigacaoCancelada','caixaPreservado',true));
 RETURN r;
END $$;
CREATE OR REPLACE FUNCTION calendario46.validar(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE s jsonb; c jsonb; p jsonb; n integer; i integer:=0; origin public.multimodal_origens%ROWTYPE; creation public.multimodal_operacoes%ROWTYPE; original jsonb;
BEGIN
 s:=public.multimodal_validar(uid,cid); c:=s->'contrato';
 SELECT * INTO STRICT origin FROM public.multimodal_origens WHERE contrato_id=cid AND user_id=uid;
 SELECT * INTO STRICT creation FROM public.multimodal_operacoes WHERE id=origin.operacao_id AND user_id=uid;
 original:=private47.estado_auditado(uid,cid,s);
 IF creation.family IS DISTINCT FROM 'multimodal_criar' OR creation.resultado IS NULL OR creation.auditoria->'payload' IS DISTINCT FROM creation.payload
 OR creation.hash_payload IS DISTINCT FROM encode(extensions.digest(creation.payload::text,'sha256'),'hex')
 OR original->'origem' IS DISTINCT FROM s->'origem' OR original->'ledger' IS DISTINCT FROM s->'ledger'
 OR ((original->'contrato')-ARRAY['data_vencimento_primeira','data_vencimento','dia_vencimento','updatedAt']) IS DISTINCT FROM (c-ARRAY['data_vencimento_primeira','data_vencimento','dia_vencimento','updatedAt'])
 OR c->>'status' IS DISTINCT FROM 'ativo' OR c->>'modalidade' IS DISTINCT FROM 'mensal' OR c->>'tipo_taxa' IS DISTINCT FROM 'mensal'
 OR EXISTS(SELECT 1 FROM public.multimodal_renovacoes WHERE contrato_id=cid)
 OR EXISTS(SELECT 1 FROM public.multimodal_operacoes WHERE user_id=uid AND family IN('multimodal_receber','multimodal_renovar') AND (payload->>'contratoId')::integer=cid AND resultado IS NOT NULL)
 OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid)
 THEN RAISE EXCEPTION '46 only genuine creation25 wholly open monthly, audited46/48 only; no receipt/renewal/fine' USING ERRCODE='23514'; END IF;
 n:=jsonb_array_length(s->'parcelas');
 IF n NOT BETWEEN 1 AND 60 OR n IS DISTINCT FROM origin.numero_inicial+(SELECT count(*) FROM obrigacoes51.adicionais WHERE contrato_id=cid AND user_id=uid) OR n IS DISTINCT FROM (c->>'num_parcelas')::int OR n IS DISTINCT FROM (c->>'numero_parcelas')::int
 OR n IS DISTINCT FROM jsonb_array_length(original->'parcelas') THEN RAISE EXCEPTION '46 count changed' USING ERRCODE='23514'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int LOOP
 i:=i+1;
 IF (p->>'numero')::int IS DISTINCT FROM i OR (p->>'numero_parcela')::int IS DISTINCT FROM i
 OR p->>'status' IS DISTINCT FROM 'pendente' OR (p->>'data_vencimento')::date<=(clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date
 OR (p->>'valor_pago')::numeric IS DISTINCT FROM 0::numeric OR (p->>'saldo_residual')::numeric IS DISTINCT FROM 0::numeric
 OR (p->>'valor_desconto')::numeric<0 OR (p->>'valor_multa')::numeric IS DISTINCT FROM 0::numeric
 OR (p->>'multa_manual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_diaria_usada')::numeric IS DISTINCT FROM 0::numeric
 OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(original->'parcelas') op WHERE (op-ARRAY['data_vencimento','updatedAt'])=(p-ARRAY['data_vencimento','updatedAt']))
 THEN RAISE EXCEPTION '46 audited installment no longer wholly open future' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN s;
END $$;
CREATE OR REPLACE FUNCTION private47.estado_auditado(uid integer,cid integer,target jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE origin public.multimodal_origens%ROWTYPE; creation public.multimodal_operacoes%ROWTYPE; op public.multimodal_operacoes%ROWTYPE; latest public.multimodal_estados%ROWTYPE;
 s jsonb; initial jsonb; c jsonb; p jsonb; line jsonb; calc jsonb; expected jsonb; afters jsonb; nc jsonb; np jsonb; ps jsonb; hist jsonb; plan jsonb;
 n integer; i integer; totalops integer; applied integer:=0; candidates integer; seen uuid[]:='{}'; stamp timestamptz; dates date[]; net numeric; principal numeric; additional numeric:=0; appended obrigacoes51.adicionais%ROWTYPE;
BEGIN
 PERFORM private47.verificar();
 -- Pure closed proof. No writes, adoption, origin bridge or runtime reseal. Locks belong to unchanged callers35/46/47.
 SELECT * INTO origin FROM public.multimodal_origens WHERE contrato_id=cid AND user_id=uid LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION '47 chain owner/origin unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT creation FROM public.multimodal_operacoes WHERE id=origin.operacao_id LIMIT 1;
 SELECT * INTO STRICT latest FROM public.multimodal_estados WHERE contrato_id=cid LIMIT 1;
 initial:=creation.auditoria->'depois'; s:=initial; c:=s->'contrato'; n:=origin.numero_inicial;
 IF creation.user_id IS DISTINCT FROM uid OR creation.family IS DISTINCT FROM 'multimodal_criar' OR creation.resultado IS NULL OR creation.concluida_em IS NULL
 OR creation.payload IS DISTINCT FROM public.multimodal_payload(uid,creation.family,creation.request)
 OR creation.hash_payload IS DISTINCT FROM private47.hash(creation.payload) OR creation.auditoria->'hashPayload' IS DISTINCT FROM to_jsonb(creation.hash_payload)
 OR creation.auditoria->'payload' IS DISTINCT FROM creation.payload OR creation.auditoria->'resultado' IS DISTINCT FROM creation.resultado OR creation.auditoria->'antes' IS DISTINCT FROM 'null'::jsonb
 OR creation.resultado->'success' IS DISTINCT FROM 'true'::jsonb OR creation.resultado->>'operationId' IS DISTINCT FROM creation.id::text OR creation.resultado->>'id' IS DISTINCT FROM cid::text
 OR s->'origem' IS DISTINCT FROM to_jsonb(origin) OR s->'renovacoes' IS DISTINCT FROM '[]'::jsonb OR n NOT BETWEEN 1 AND 60 OR jsonb_array_length(s->'parcelas') IS DISTINCT FROM n
 OR origin.modalidade IS DISTINCT FROM 'mensal' OR origin.tipo_taxa IS DISTINCT FROM 'mensal' OR origin.regra IS DISTINCT FROM 'multimodal_v1'
 OR c->>'id' IS DISTINCT FROM cid::text OR c->>'user_id' IS DISTINCT FROM uid::text OR c->>'cliente_id' IS DISTINCT FROM origin.cliente_id::text
 OR c->>'conta_caixa_id' IS DISTINCT FROM origin.conta_id::text OR c->'koletor_id' IS DISTINCT FROM coalesce(to_jsonb(origin.koletor_id),'null'::jsonb)
 OR c->'contrato_origem_id' IS DISTINCT FROM 'null'::jsonb OR c->>'status' IS DISTINCT FROM 'ativo' OR c->>'modalidade' IS DISTINCT FROM 'mensal' OR c->>'tipo_taxa' IS DISTINCT FROM 'mensal'
 OR c->>'num_parcelas' IS DISTINCT FROM n::text OR c->>'numero_parcelas' IS DISTINCT FROM n::text
 OR (c->>'valor_principal')::numeric IS DISTINCT FROM (creation.payload->>'valorPrincipal')::numeric OR (c->>'taxa_juros')::numeric IS DISTINCT FROM (creation.payload->>'taxaJuros')::numeric
 OR (c->>'multa_atraso')::numeric IS DISTINCT FROM (creation.payload->>'multaAtraso')::numeric OR (c->>'juros_mora_diario')::numeric IS DISTINCT FROM (creation.payload->>'jurosMoraDiario')::numeric
 OR c->>'data_inicio' IS DISTINCT FROM creation.payload->>'dataInicio' OR creation.payload->>'dataDesembolso' IS DISTINCT FROM creation.payload->>'dataInicio'
 OR c->'descricao' IS DISTINCT FROM creation.payload->'descricao' OR c->'observacoes' IS DISTINCT FROM creation.payload->'observacoes'
 THEN RAISE EXCEPTION '47 chain genuine creation25 proof inconsistent' USING ERRCODE='23514'; END IF;
 calc:=public.multimodal_calcular('mensal',(creation.payload->>'valorPrincipal')::numeric,(creation.payload->>'taxaJuros')::numeric,n);
 IF creation.auditoria->'extra' IS DISTINCT FROM calc OR (c->>'total_contrato')::numeric IS DISTINCT FROM (calc->>'total')::numeric
 OR (c->>'valor_parcela')::numeric IS DISTINCT FROM (calc->>'referencia')::numeric OR jsonb_array_length(creation.payload->'vencimentos') IS DISTINCT FROM n
 OR c->>'data_vencimento_primeira' IS DISTINCT FROM creation.payload->'vencimentos'->>0 OR c->>'data_vencimento' IS DISTINCT FROM creation.payload->'vencimentos'->>(n-1)
 OR (c->>'dia_vencimento')::int IS DISTINCT FROM extract(day FROM (c->>'data_vencimento_primeira')::date)::int
 OR jsonb_array_length(s->'ledger') IS DISTINCT FROM 1 OR jsonb_array_length(s->'historico') IS DISTINCT FROM 1
 OR NOT EXISTS(SELECT 1 FROM public.multimodal_pernas m JOIN public.transacoes_caixa t ON t.id=m.transacao_id WHERE m.operacao_id=creation.id AND m.transacao_id=origin.transacao_id AND m.snapshot=to_jsonb(t) AND s->'ledger'=jsonb_build_array(to_jsonb(t)) AND t.user_id=uid AND t.contrato_id=cid AND t.parcela_id IS NULL AND t.conta_caixa_id=origin.conta_id AND t.tipo='saida' AND t.categoria='emprestimo_liberado' AND t.valor=(c->>'valor_principal')::numeric LIMIT 1)
 THEN RAISE EXCEPTION '47 chain creation25 math/cash inconsistent' USING ERRCODE='23514'; END IF;
 i:=0;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'numero')::int LIMIT 60 LOOP
  line:=calc->'linhas'->i;
  IF p->>'numero' IS DISTINCT FROM (i+1)::text OR p->>'numero_parcela' IS DISTINCT FROM (i+1)::text OR p->>'contrato_id' IS DISTINCT FROM cid::text OR p->>'user_id' IS DISTINCT FROM uid::text
  OR p->>'cliente_id' IS DISTINCT FROM origin.cliente_id::text OR p->>'conta_caixa_id' IS DISTINCT FROM origin.conta_id::text OR p->'koletor_id' IS DISTINCT FROM coalesce(to_jsonb(origin.koletor_id),'null'::jsonb)
  OR (p->>'valor')::numeric IS DISTINCT FROM (line->>'valor')::numeric OR (p->>'valor_original')::numeric IS DISTINCT FROM (line->>'valor')::numeric OR (p->>'valor_juros')::numeric IS DISTINCT FROM (line->>'juros')::numeric
  OR (p->>'valor_pago')::numeric IS DISTINCT FROM 0::numeric OR (p->>'saldo_residual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'valor_desconto')::numeric IS DISTINCT FROM 0::numeric
  OR (p->>'valor_multa')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_manual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_diaria_usada')::numeric IS DISTINCT FROM 0::numeric OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb
  OR p->>'data_vencimento' IS DISTINCT FROM creation.payload->'vencimentos'->>i OR p->>'data_vencimento' IS DISTINCT FROM public.multimodal_data((creation.payload->'vencimentos'->>0)::date,'mensal',i)::text
  OR p->>'status' NOT IN('pendente','atrasada','vencendo_hoje') OR NOT EXISTS(SELECT 1 FROM public.parcelas actual WHERE actual.id=(p->>'id')::int AND actual.contrato_id=cid AND actual.user_id=uid LIMIT 1)
  THEN RAISE EXCEPTION '47 chain original installment math/identity inconsistent' USING ERRCODE='23514'; END IF;
  i:=i+1;
 END LOOP;
 IF creation.resultado->'parcelasIds' IS DISTINCT FROM (SELECT jsonb_agg((j->>'id')::int ORDER BY (j->>'numero')::int) FROM jsonb_array_elements(s->'parcelas') j LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.multimodal_renovacoes WHERE contrato_id=cid LIMIT 1) OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid LIMIT 1)
 OR EXISTS(SELECT 1 FROM public.multimodal_operacoes x WHERE x.id<>creation.id AND (x.payload->>'contratoId'=cid::text OR x.resultado->>'contratoId'=cid::text OR x.resultado->>'id'=cid::text OR x.auditoria->'antes'->'contrato'->>'id'=cid::text OR x.auditoria->'depois'->'contrato'->>'id'=cid::text)
 AND (x.user_id IS DISTINCT FROM uid OR x.family NOT IN('multimodal_calendario46','multimodal_manutencao48') OR (x.resultado IS NULL AND pg_xact_status(x.xmin::text::xid8) IS DISTINCT FROM 'in progress')) LIMIT 1)
 THEN RAISE EXCEPTION '47 chain other owner/family/receipt/renewal/fine unavailable' USING ERRCODE='23514'; END IF;
 SELECT count(*) INTO totalops FROM public.multimodal_operacoes x WHERE x.id<>creation.id AND x.resultado IS NOT NULL AND (x.payload->>'contratoId'=cid::text OR x.resultado->>'contratoId'=cid::text OR x.auditoria->'antes'->'contrato'->>'id'=cid::text OR x.auditoria->'depois'->'contrato'->>'id'=cid::text) LIMIT 1;
 IF totalops>1024 THEN RAISE EXCEPTION '47 chain closed proof bound exceeded' USING ERRCODE='54000'; END IF;
 WHILE applied<totalops LOOP
  SELECT count(*) INTO candidates FROM public.multimodal_operacoes x WHERE x.user_id=uid AND x.id<>creation.id AND NOT(x.id=ANY(seen)) AND x.resultado IS NOT NULL AND x.payload->>'contratoId'=cid::text AND x.auditoria->'antes'=s LIMIT 1;
  IF candidates<>1 THEN RAISE EXCEPTION '47 chain missing/branched/inconsistent predecessor' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT op FROM public.multimodal_operacoes x WHERE x.user_id=uid AND x.id<>creation.id AND NOT(x.id=ANY(seen)) AND x.resultado IS NOT NULL AND x.payload->>'contratoId'=cid::text AND x.auditoria->'antes'=s LIMIT 1;
  afters:=op.auditoria->'depois'; stamp:=(afters->'contrato'->>'updatedAt')::timestamptz; hist:=afters->'historico'->jsonb_array_length(s->'historico'); expected:=s;
  IF op.concluida_em IS NULL OR op.payload IS DISTINCT FROM public.multimodal_payload(uid,op.family,op.request) OR op.hash_payload IS DISTINCT FROM private47.hash(op.payload)
  OR op.auditoria->'payload' IS DISTINCT FROM op.payload OR op.auditoria->>'hashPayload' IS DISTINCT FROM op.hash_payload OR op.auditoria->'resultado' IS DISTINCT FROM op.resultado
  OR op.resultado->'success' IS DISTINCT FROM 'true'::jsonb OR op.resultado->>'operationId' IS DISTINCT FROM op.id::text OR op.resultado->>'idempotencyKey' IS DISTINCT FROM op.chave::text OR op.resultado->>'contratoId' IS DISTINCT FROM cid::text
  OR op.request->>'estadoHash' IS DISTINCT FROM private47.hash(s) OR op.auditoria->'extra'->>'predecessorEstadoHash' IS DISTINCT FROM private47.hash(s)
  OR op.auditoria->'extra'->>'origemOperacao' IS DISTINCT FROM creation.id::text OR op.auditoria->'extra'->>'familia' IS DISTINCT FROM op.family
  OR stamp IS NULL OR stamp<(s->'contrato'->>'updatedAt')::timestamptz OR op.concluida_em<stamp
  OR hist IS NULL OR hist->>'contrato_id' IS DISTINCT FROM cid::text OR hist->>'user_id' IS DISTINCT FROM uid::text OR (hist->>'created_at')::timestamptz IS DISTINCT FROM stamp
  OR hist->'valor_anterior' IS DISTINCT FROM 'null'::jsonb OR hist->'valor_novo' IS DISTINCT FROM 'null'::jsonb
  OR EXISTS(SELECT 1 FROM public.multimodal_pernas WHERE operacao_id=op.id LIMIT 1)
  THEN RAISE EXCEPTION '47 chain operation/hash/version/history/cash inconsistent' USING ERRCODE='23514'; END IF;
  IF op.family='multimodal_calendario46' THEN
   SELECT array_agg(value::date ORDER BY ord) INTO dates FROM jsonb_array_elements_text(op.request->'vencimentos') WITH ORDINALITY a(value,ord) LIMIT 1;
   PERFORM manutencao44.agenda(cid,dates,(s->'contrato'->>'data_inicio')::date,n);
   IF op.request IS DISTINCT FROM manutencao44.request(cid,private47.hash(s),dates,op.request->>'motivo') OR dates[1]<=(stamp AT TIME ZONE 'America/Sao_Paulo')::date
   OR hist->>'tipo' IS DISTINCT FROM 'edicao_calendario' OR hist->>'descricao' IS DISTINCT FROM 'Calendário25 auditado '||op.id::text||': '||btrim(op.request->>'motivo')
   OR op.resultado->'vencimentos' IS DISTINCT FROM to_jsonb(dates) OR op.auditoria->'extra'->>'delta' IS DISTINCT FROM 'dates+timestamps+append_history_only'
   THEN RAISE EXCEPTION '47 chain calendar delta inconsistent' USING ERRCODE='23514'; END IF;
   ps:='[]';
   FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'id')::int LIMIT 60 LOOP
    np:=p||jsonb_build_object('data_vencimento',dates[(p->>'numero')::int],'updatedAt',stamp); ps:=ps||jsonb_build_array(np);
   END LOOP;
   nc:=(s->'contrato')||jsonb_build_object('data_vencimento_primeira',dates[1],'data_vencimento',dates[n],'dia_vencimento',extract(day FROM dates[1])::int,'updatedAt',stamp);
   expected:=jsonb_set(jsonb_set(expected,'{parcelas}',ps),'{contrato}',nc);
  ELSIF op.family='multimodal_manutencao48' THEN
   PERFORM manutencao48.verificar();
   IF op.request->'alteracao'->>'acao' NOT IN('juros','valor','desconto','adicionar','editar') OR op.request IS DISTINCT FROM manutencao48.request(cid,private47.hash(s),op.request->'alteracao',op.request->>'motivo')
   OR hist->>'tipo' IS DISTINCT FROM 'manutencao_'||(op.request->'alteracao'->>'acao') OR hist->>'descricao' IS DISTINCT FROM 'Manutenção25 '||op.id::text||': '||(op.request->>'motivo')
   OR op.auditoria->'extra'->'caixaPreservado' IS DISTINCT FROM 'true'::jsonb
   THEN RAISE EXCEPTION '47 chain maintenance action/history inconsistent' USING ERRCODE='23514'; END IF;
   IF op.request->'alteracao'->>'acao'='adicionar' THEN
 SELECT * INTO STRICT appended FROM obrigacoes51.adicionais WHERE operacao48=op.id AND user_id=uid AND contrato_id=cid LIMIT 1;
 IF appended.hash_linha IS DISTINCT FROM obrigacoes51.hash(appended.linha_inicial) OR appended.valor IS DISTINCT FROM (op.request->'alteracao'->>'valor')::numeric OR appended.numero<>n+1 OR appended.parcela_id IS DISTINCT FROM (appended.linha_inicial->>'id')::int THEN RAISE EXCEPTION '51 append witness inválido' USING ERRCODE='23514'; END IF;
 plan:=obrigacoes51.plano(s,op.request->'alteracao',stamp,appended.linha_inicial);n:=n+1;additional:=additional+appended.valor;
 ELSE plan:=manutencao48.plano(s,op.request->'alteracao',stamp); END IF;
   IF op.resultado->>'totalContrato' IS DISTINCT FROM plan->>'totalContrato' OR op.resultado->>'jurosTotal' IS DISTINCT FROM plan->>'jurosTotal' OR op.resultado->>'obrigacaoCancelada' IS DISTINCT FROM '0.00'
   OR op.auditoria->'extra'->>'compensacaoObrigacao' IS DISTINCT FROM '0.00' THEN RAISE EXCEPTION '47 chain maintenance totals inconsistent' USING ERRCODE='23514'; END IF;
   expected:=jsonb_set(jsonb_set(expected,'{parcelas}',plan->'parcelas'),'{contrato}',plan->'contrato');
  ELSE RAISE EXCEPTION '47 chain family not allowlisted' USING ERRCODE='23514'; END IF;
  expected:=jsonb_set(expected,'{historico}',s->'historico'||jsonb_build_array(hist));
  IF expected IS DISTINCT FROM afters THEN RAISE EXCEPTION '47 chain full snapshot transition inconsistent' USING ERRCODE='23514'; END IF;
  -- JSONB numeric equality is scale-insensitive; hashes bind audited text exactly. Preserve its existing representation only AFTER full deterministic delta equality. Never rewrite/reseal it.
  s:=afters; seen:=array_append(seen,op.id); applied:=applied+1;
 END LOOP;
 SELECT sum((j->>'valor_original')::numeric),sum((j->>'valor_original')::numeric-(j->>'valor_juros')::numeric) INTO net,principal FROM jsonb_array_elements(s->'parcelas') j LIMIT 1;
 IF s IS DISTINCT FROM target OR latest.user_id IS DISTINCT FROM uid OR latest.snapshot IS DISTINCT FROM s OR latest.hash_snapshot IS DISTINCT FROM private47.hash(s)
 OR latest.operacao_id IS DISTINCT FROM (CASE WHEN applied=0 THEN creation.id ELSE op.id END)
 OR s->'origem' IS DISTINCT FROM initial->'origem' OR s->'ledger' IS DISTINCT FROM initial->'ledger' OR s->'renovacoes' IS DISTINCT FROM '[]'::jsonb
 OR net IS DISTINCT FROM (s->'contrato'->>'total_contrato')::numeric OR principal-additional IS DISTINCT FROM (initial->'contrato'->>'valor_principal')::numeric
 THEN RAISE EXCEPTION '47 chain terminal snapshot/principal/ledger/version inconsistent' USING ERRCODE='23514', DETAIL=jsonb_build_object('applied',applied,'targetDiff',s IS DISTINCT FROM target,'latestDiff',latest.snapshot IS DISTINCT FROM s,'hashDiff',latest.hash_snapshot IS DISTINCT FROM private47.hash(s),'op',op.id,'latestOp',latest.operacao_id,'net',net,'total',s->'contrato'->>'total_contrato','principal',principal,'initialPrincipal',initial->'contrato'->>'valor_principal','originDiff',s->'origem' IS DISTINCT FROM initial->'origem','ledgerDiff',s->'ledger' IS DISTINCT FROM initial->'ledger')::text; END IF;
 RETURN s;
END $$;
CREATE OR REPLACE FUNCTION private47.cotar(uid integer,req jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE r jsonb; c public.contratos%ROWTYPE; p public.parcelas%ROWTYPE; o public.multimodal_origens%ROWTYPE; op public.multimodal_operacoes%ROWTYPE;
 s jsonb; state jsonb; calc jsonb; line jsonb; rows jsonb:='[]'; before_count integer; i integer:=0; n integer;
 saldo numeric:=0; capital numeric:=0; embutidos numeric:=0; encargos numeric:=0; mc numeric; mora numeric; enc jsonb; q jsonb;
 instante timestamptz; hoje date; additional numeric:=0;
BEGIN
 PERFORM private47.verificar(); r:=public.reparcelamento43_request(req,false);
 IF uid IS NULL OR uid<=0 THEN RAISE EXCEPTION 'Owner47 inválido' USING ERRCODE='22023'; END IF;
 SELECT * INTO o FROM public.multimodal_origens WHERE contrato_id=(r->>'contratoId')::int AND user_id=uid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Origem atual25/35 indisponível; legados usam fluxo43' USING ERRCODE='42501'; END IF;
 -- Ordem e locks reais do writer35, sem escolher owner ou conta pelo request.
 PERFORM public.multimodal_travar(uid,o.contrato_id); s:=public.multimodal_validar(uid,o.contrato_id);
 instante:=clock_timestamp(); hoje:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;
 SELECT * INTO STRICT c FROM public.contratos WHERE id=o.contrato_id;
 SELECT * INTO STRICT op FROM public.multimodal_operacoes WHERE id=o.operacao_id;
 SELECT count(*)::int INTO before_count FROM public.parcelas WHERE contrato_id=c.id;
 IF c.user_id IS DISTINCT FROM uid OR c.status IS DISTINCT FROM 'ativo' OR c.contrato_origem_id IS NOT NULL
 OR c.modalidade IS DISTINCT FROM 'mensal' OR c.modalidade IS DISTINCT FROM o.modalidade
 OR c.tipo_taxa IS DISTINCT FROM o.tipo_taxa OR c.num_parcelas IS DISTINCT FROM c.numero_parcelas OR before_count IS DISTINCT FROM o.numero_inicial+(SELECT count(*) FROM obrigacoes51.adicionais WHERE contrato_id=c.id AND user_id=uid)
 OR c.num_parcelas IS DISTINCT FROM before_count OR op.family IS DISTINCT FROM 'multimodal_criar' OR op.resultado IS NULL
 OR op.resultado->>'id' IS DISTINCT FROM c.id::text
 OR EXISTS(SELECT 1 FROM public.multimodal_renovacoes WHERE contrato_id=c.id)
 OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=c.id)
 OR EXISTS(SELECT 1 FROM public.reparcelamento43_estados WHERE contrato_id=c.id) OR EXISTS(SELECT 1 FROM private47.cadeia WHERE origem_id=c.id)
 OR EXISTS(SELECT 1 FROM public.multimodal_operacoes WHERE resultado->>'contratoId'=c.id::text AND family NOT IN('multimodal_calendario46','multimodal_manutencao48') LIMIT 1)
 THEN RAISE EXCEPTION 'Origem47 inelegível: recebida, renovada, multa36 ou shape ambíguo não suportado' USING ERRCODE='0A000'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=c.cliente_id AND user_id=uid AND ativo)
 OR NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=c.conta_caixa_id AND user_id=uid AND ativo)
 OR (c.koletor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.koletores WHERE id=c.koletor_id AND user_id=uid AND ativo)) THEN RAISE EXCEPTION 'Vínculo47 indisponível' USING ERRCODE='42501'; END IF;
 PERFORM private47.estado_auditado(uid,c.id,s);
 -- Livro da origem precisa ser exatamente a única saída comprovada, nunca recebimento inventado.
 IF jsonb_array_length(s->'ledger')<>1 OR NOT EXISTS(SELECT 1 FROM public.multimodal_pernas m JOIN public.transacoes_caixa t ON t.id=m.transacao_id WHERE m.operacao_id=op.id AND t.id=o.transacao_id AND m.snapshot=to_jsonb(t)
 AND t.user_id=uid AND t.contrato_id=c.id AND t.parcela_id IS NULL AND t.conta_caixa_id=c.conta_caixa_id AND t.tipo='saida' AND t.categoria='emprestimo_liberado' AND t.valor=c.valor_principal) THEN RAISE EXCEPTION '47 origem/livro ambíguo' USING ERRCODE='23514'; END IF;
 FOR p IN SELECT * FROM public.parcelas WHERE contrato_id=c.id ORDER BY numero LOOP
 i:=i+1;
 IF p.numero IS DISTINCT FROM i OR p.numero_parcela IS DISTINCT FROM i OR p.user_id IS DISTINCT FROM uid OR p.cliente_id IS DISTINCT FROM c.cliente_id
 OR p.conta_caixa_id IS DISTINCT FROM c.conta_caixa_id OR p.koletor_id IS DISTINCT FROM c.koletor_id
 OR p.status NOT IN('pendente','atrasada','vencendo_hoje') OR p.valor_pago IS DISTINCT FROM 0::numeric OR p.saldo_residual IS DISTINCT FROM 0::numeric
 OR p.valor IS DISTINCT FROM p.valor_original OR NOT public.multimodal_moeda(p.valor_original) OR p.valor_original<=0
 OR NOT public.multimodal_moeda(p.valor_juros) OR p.valor_juros>p.valor_original OR p.data_pagamento IS NOT NULL
 OR p.valor_multa IS DISTINCT FROM 0::numeric OR p.multa_diaria_usada IS DISTINCT FROM 0::numeric OR p.multa_manual IS DISTINCT FROM 0::numeric OR p.valor_desconto<0
 THEN RAISE EXCEPTION 'Parcela47 inelegível: parcial/paga/transferida não suportada' USING ERRCODE='0A000'; END IF;
 mc:=0; mora:=0;
 enc:=public.ciclo_encargos(p.valor_original,c.multa_atraso,c.juros_mora_diario,p.data_vencimento,instante);
 IF (enc->>'multa')::numeric<>0 OR (enc->>'mora')::numeric<>0 THEN RAISE EXCEPTION '47 recorte sem multa/mora incorrida' USING ERRCODE='0A000'; END IF;
 IF (r->>'incluirMultas')::boolean THEN
 enc:=public.ciclo_encargos(p.valor_original,c.multa_atraso,c.juros_mora_diario,p.data_vencimento,instante); mc:=(enc->>'multa')::numeric; mora:=(enc->>'mora')::numeric;
 END IF;
 saldo:=saldo+p.valor_original+mc+mora; capital:=capital+p.valor_original-p.valor_juros; embutidos:=embutidos+p.valor_juros; encargos:=encargos+mc+mora;
 END LOOP;
 SELECT coalesce(sum(valor),0) INTO additional FROM obrigacoes51.adicionais WHERE contrato_id=c.id AND user_id=uid; capital:=capital-additional;
 IF capital IS DISTINCT FROM c.valor_principal OR saldo-encargos IS DISTINCT FROM c.total_contrato OR NOT public.multimodal_moeda(saldo) THEN RAISE EXCEPTION 'Saldo/principal47 não conservado' USING ERRCODE='23514'; END IF;
 n:=(r->>'numeroParcelas')::int; calc:=public.multimodal_calcular('mensal',saldo,(r->>'taxaJuros')::numeric,n); i:=0;
 FOR line IN SELECT value FROM jsonb_array_elements(calc->'linhas') LOOP
 rows:=rows||jsonb_build_array(jsonb_build_object('numero',i+1,'valor',(line->>'valor')::numeric(12,2)::text,'juros',(line->>'juros')::numeric(12,2)::text,'principal',(line->>'principal')::numeric(12,2)::text,'vencimento',public.multimodal_data((r->>'dataInicio')::date,'mensal',i)::text)); i:=i+1;
 END LOOP;
 state:=jsonb_build_object('origem',s,'dia',hoje,'conta',(SELECT to_jsonb(a) FROM public.contas_caixa a WHERE id=o.conta_id),
 'livro',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]'::jsonb) FROM public.transacoes_caixa t WHERE conta_caixa_id=o.conta_id),
 'cliente',(SELECT jsonb_build_array(id,user_id,ativo) FROM public.clientes WHERE id=o.cliente_id),'koletor',(SELECT jsonb_build_array(id,user_id,ativo) FROM public.koletores WHERE id=o.koletor_id));
 q:=jsonb_build_object('regra','reparcelamento47_cotacao_v2','userId',uid,'contratoId',c.id,'contaCaixaId',o.conta_id,'dataCalculo',hoje::text,'request',r,
 'estadoHash',encode(extensions.digest(state::text,'sha256'),'hex'),'origemOperationId',op.id,'modalidadeOrigem',o.modalidade,'principalOriginal',capital::numeric(12,2)::text,
 'jurosEmbutidos',embutidos::numeric(12,2)::text,'saldoDevedor',saldo::numeric(12,2)::text,'encargos',encargos::numeric(12,2)::text,
 'valorNovaParcela',(calc->>'referencia')::numeric(12,2)::text,'totalNovo',(calc->>'total')::numeric(12,2)::text,'jurosNovos',(calc->>'juros')::numeric(12,2)::text,
 'qtdParcelasAbertas',before_count,'parcelas',rows,'executavel',true);
 IF additional>0 THEN q:=q||jsonb_build_object('regra','reparcelamento47_cotacao_v3','obrigacaoAdicional',additional::numeric(12,2)::text); END IF;
 RETURN q;
END $$;
CREATE OR REPLACE FUNCTION private47.executar(uid integer,k uuid,req jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE r jsonb; saved private47.cotacoes%ROWTYPE; op private47.operacoes%ROWTYPE; f private47.fences%ROWTYPE; q jsonb; before47 jsonb; after47 jsonb; expected jsonb; predecessor jsonb; ps jsonb:='[]'; ids integer[]:='{}'; c jsonb; p jsonb; h jsonb; v jsonb; successor jsonb; sc jsonb; audit jsonb; result47 jsonb; root integer; cid integer; i integer:=0; instante timestamptz; hoje date; cash jsonb; cash_after jsonb;
BEGIN
 PERFORM private47.verificar(); r:=private47.request(req); PERFORM private47.barreira(uid,k);
 root:=(r->>'contratoId')::int;
 PERFORM public.multimodal_travar(uid,root);
 SELECT * INTO f FROM private47.fences WHERE user_id=uid AND chave=k;
 IF FOUND THEN
 IF f.request IS DISTINCT FROM r THEN RAISE EXCEPTION '47 fence payload divergente' USING ERRCODE='23505'; END IF;
 IF f.hash_request IS DISTINCT FROM private47.hash(r) THEN RAISE EXCEPTION '47 fence adulterado' USING ERRCODE='23514'; END IF;
 RAISE EXCEPTION '47 UUID fenced permanente' USING ERRCODE='55000'; END IF;
 SELECT * INTO op FROM private47.operacoes WHERE user_id=uid AND chave=k;
 IF FOUND THEN
 IF op.request IS DISTINCT FROM r THEN RAISE EXCEPTION '47 UUID payload divergente' USING ERRCODE='23505'; END IF;
 PERFORM private47.validar_op(op.id); RETURN op.resultado||jsonb_build_object('repetida',true); END IF;
 IF (SELECT executar FROM private47.flags ORDER BY id DESC LIMIT 1) IS DISTINCT FROM true THEN RAISE EXCEPTION '47 execução OFF; recovery segue permitido' USING ERRCODE='55000'; END IF;
 SELECT * INTO saved FROM private47.cotacoes WHERE id=(r->>'cotacaoId')::uuid AND user_id=uid;
 IF NOT FOUND THEN RAISE EXCEPTION '47 cotação não pertence à empresa' USING ERRCODE='42501'; END IF;
 IF saved.request IS DISTINCT FROM r-ARRAY['cotacaoId','cotacaoHash','estadoHash'] OR saved.hash_cotacao IS DISTINCT FROM private47.hash(saved.cotacao) OR saved.hash_cotacao IS DISTINCT FROM r->>'cotacaoHash' OR saved.cotacao->>'estadoHash' IS DISTINCT FROM r->>'estadoHash' THEN RAISE EXCEPTION '47 cotação/request divergente' USING ERRCODE='23505'; END IF;
 q:=private47.cotar(uid,saved.request);
 IF q IS DISTINCT FROM saved.cotacao-'cotacaoId' THEN RAISE EXCEPTION '47 cotação/estado/BRT expirou após lock' USING ERRCODE='40001'; END IF;
 before47:=public.multimodal_validar(uid,root); expected:=before47;
 SELECT jsonb_build_object('conta',to_jsonb(a),'ledger',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]') FROM public.transacoes_caixa t WHERE conta_caixa_id=a.id)) INTO cash FROM public.contas_caixa a WHERE id=(q->>'contaCaixaId')::int;
 predecessor:=jsonb_build_object('origens',(SELECT jsonb_agg(to_jsonb(o) ORDER BY contrato_id) FROM public.multimodal_origens o WHERE user_id=uid),'ops',(SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM public.multimodal_operacoes o WHERE user_id=uid),'estados',(SELECT jsonb_agg(to_jsonb(o) ORDER BY contrato_id) FROM public.multimodal_estados o WHERE user_id=uid),'pernas',(SELECT jsonb_agg(to_jsonb(o) ORDER BY operacao_id) FROM public.multimodal_pernas o WHERE operacao_id IN(SELECT id FROM public.multimodal_operacoes WHERE user_id=uid)));
 instante:=clock_timestamp(); hoje:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;
 INSERT INTO private47.operacoes(user_id,chave,acao,request,hash_request) VALUES(uid,k,'reparcelar',r,private47.hash(r)) RETURNING * INTO op;
 c:=before47->'contrato';
 sc:=public.multimodal_nova_linha('contratos')||jsonb_build_object('user_id',uid,'cliente_id',(c->>'cliente_id')::int,'koletor_id',(c->>'koletor_id')::int,'conta_caixa_id',(c->>'conta_caixa_id')::int,'contrato_origem_id',root,'modalidade','mensal','tipo_taxa','mensal','valor_principal',(q->>'saldoDevedor')::numeric,'taxa_juros',(r->>'taxaJuros')::numeric,'num_parcelas',(r->>'numeroParcelas')::int,'numero_parcelas',(r->>'numeroParcelas')::int,'valor_parcela',(q->>'valorNovaParcela')::numeric,'total_contrato',(q->>'totalNovo')::numeric,'data_inicio',(r->>'dataInicio')::date,'data_vencimento_primeira',(r->>'dataInicio')::date,'data_vencimento',(q->'parcelas'->((r->>'numeroParcelas')::int-1)->>'vencimento')::date,'dia_vencimento',extract(day FROM (r->>'dataInicio')::date)::int,'descricao','Reparcelamento47 sem desembolso '||op.id::text,'multa_atraso',(c->>'multa_atraso')::numeric,'juros_mora_diario',(c->>'juros_mora_diario')::numeric,'status','ativo','createdAt',instante,'updatedAt',instante);
 cid:=(sc->>'id')::int;
 INSERT INTO private47.cadeia(origem_id,sucessor_id,user_id,operacao_id,origem_operation_id,principal_original,juros_embutidos,saldo_transferido,obrigacao_adicional) VALUES(root,cid,uid,op.id,(q->>'origemOperationId')::uuid,(q->>'principalOriginal')::numeric,(q->>'jurosEmbutidos')::numeric,(q->>'saldoDevedor')::numeric,coalesce((q->>'obrigacaoAdicional')::numeric,0));
 PERFORM private47.escrever(op.id,'contratos',NULL,sc);
 FOR v IN SELECT value FROM jsonb_array_elements(q->'parcelas') LOOP
 i:=i+1;
 p:=public.multimodal_nova_linha('parcelas')||jsonb_build_object('user_id',uid,'contrato_id',cid,'cliente_id',(c->>'cliente_id')::int,'koletor_id',(c->>'koletor_id')::int,'conta_caixa_id',(c->>'conta_caixa_id')::int,'numero',i,'numero_parcela',i,'valor',(v->>'valor')::numeric,'valor_original',(v->>'valor')::numeric,'valor_juros',(v->>'juros')::numeric,'valor_pago',0,'valor_multa',0,'valor_desconto',0,'saldo_residual',0,'multa_manual',0,'multa_diaria_usada',0,'data_vencimento',(v->>'vencimento')::date,'data_pagamento',NULL,'status',CASE WHEN (v->>'vencimento')::date<hoje THEN 'atrasada' WHEN (v->>'vencimento')::date=hoje THEN 'vencendo_hoje' ELSE 'pendente' END,'createdAt',instante,'updatedAt',instante);
 PERFORM private47.escrever(op.id,'parcelas',NULL,p); ps:=ps||jsonb_build_array(p); ids:=array_append(ids,(p->>'id')::int);
 END LOOP;
 h:=public.multimodal_nova_linha('contrato_historico')||jsonb_build_object('user_id',uid::text,'contrato_id',cid,'tipo','reparcelamento','descricao','Sucessor47 da origem25 #'||root::text||' operação '||op.id::text,'valor_anterior',0,'valor_novo',(q->>'totalNovo')::numeric,'created_at',instante);
 PERFORM private47.escrever(op.id,'contrato_historico',NULL,h);
 successor:=jsonb_build_object('contrato',sc,'parcelas',ps,'ledger','[]'::jsonb,'historico',jsonb_build_array(h),'origem',NULL,'renovacoes','[]'::jsonb);
 ps:='[]';
 FOR v IN SELECT value FROM jsonb_array_elements(before47->'parcelas') LOOP
 p:=v||jsonb_build_object('status','cancelada','updatedAt',instante); PERFORM private47.escrever(op.id,'parcelas',v,p); ps:=ps||jsonb_build_array(p);
 END LOOP;
 expected:=jsonb_set(expected,'{parcelas}',ps);
 c:=c||jsonb_build_object('status','cancelado','updatedAt',instante);
 PERFORM private47.escrever(op.id,'contratos',before47->'contrato',c); expected:=jsonb_set(expected,'{contrato}',c);
 h:=public.multimodal_nova_linha('contrato_historico')||jsonb_build_object('user_id',uid::text,'contrato_id',root,'tipo','reparcelamento','descricao','Saldo transferido47 sem dinheiro para #'||cid::text||' operação '||op.id::text,'valor_anterior',(q->>'saldoDevedor')::numeric,'valor_novo',0,'created_at',instante);
 PERFORM private47.escrever(op.id,'contrato_historico',NULL,h); expected:=jsonb_set(expected,'{historico}',expected->'historico'||jsonb_build_array(h));
 after47:=public.multimodal_snapshot(root);
 SELECT jsonb_build_object('conta',to_jsonb(a),'ledger',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]') FROM public.transacoes_caixa t WHERE conta_caixa_id=a.id)) INTO cash_after FROM public.contas_caixa a WHERE id=(q->>'contaCaixaId')::int;
 IF cash IS DISTINCT FROM cash_after OR after47 IS DISTINCT FROM expected OR public.multimodal_snapshot(cid) IS DISTINCT FROM successor OR predecessor IS DISTINCT FROM jsonb_build_object('origens',(SELECT jsonb_agg(to_jsonb(o) ORDER BY contrato_id) FROM public.multimodal_origens o WHERE user_id=uid),'ops',(SELECT jsonb_agg(to_jsonb(o) ORDER BY id) FROM public.multimodal_operacoes o WHERE user_id=uid),'estados',(SELECT jsonb_agg(to_jsonb(o) ORDER BY contrato_id) FROM public.multimodal_estados o WHERE user_id=uid),'pernas',(SELECT jsonb_agg(to_jsonb(o) ORDER BY operacao_id) FROM public.multimodal_pernas o WHERE operacao_id IN(SELECT id FROM public.multimodal_operacoes WHERE user_id=uid))) OR (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date IS DISTINCT FROM (q->>'dataCalculo')::date THEN RAISE EXCEPTION '47 delta financeiro/civil inesperado; não selar' USING ERRCODE='23514'; END IF;
 result47:=jsonb_build_object('success',true,'regra','reparcelamento47_v2','userId',uid,'idempotencyKey',k,'operationId',op.id,'contratoOrigemId',root,'contratoId',cid,'raizId',root,'contaCaixaId',(q->>'contaCaixaId')::int,'parcelasIds',to_jsonb(ids),'saldoTransferido',q->>'saldoDevedor','principalOriginal',q->>'principalOriginal','jurosEmbutidos',q->>'jurosEmbutidos','jurosNovos',q->>'jurosNovos','totalNovo',q->>'totalNovo','desembolso','0.00','repetida',false);
 IF q ? 'obrigacaoAdicional' THEN result47:=result47||jsonb_build_object('regra','reparcelamento47_v3','obrigacaoAdicional',q->>'obrigacaoAdicional'); END IF;
 audit:=jsonb_build_object('acao','reparcelar','request',r,'cotacao',saved.cotacao,'antes',before47,'depoisOrigem',expected,'sucessor',successor,'predecessorHash',private47.hash(predecessor),'cashHash',private47.hash(cash),'resultado',result47);
 UPDATE private47.operacoes SET resultado=result47,auditoria=audit,hash_auditoria=private47.hash(audit),concluida_em=clock_timestamp() WHERE id=op.id;
 PERFORM private47.validar(uid,cid); RETURN result47;
END $$;
CREATE OR REPLACE FUNCTION private47.validar_op(oid47 uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE op private47.operacoes%ROWTYPE; ch private47.cadeia%ROWTYPE; q private47.cotacoes%ROWTYPE; a jsonb; b jsonb; v jsonb; old35 jsonb;
BEGIN
 SELECT * INTO STRICT op FROM private47.operacoes WHERE id=oid47;
 SELECT * INTO STRICT ch FROM private47.cadeia WHERE operacao_id=oid47;
 SELECT * INTO STRICT q FROM private47.cotacoes WHERE id=(op.request->>'cotacaoId')::uuid AND user_id=op.user_id;
 a:=op.auditoria->'antes'; b:=op.auditoria->'depoisOrigem';
 IF ch.obrigacao_adicional IS DISTINCT FROM coalesce((q.cotacao->>'obrigacaoAdicional')::numeric,0) OR (ch.obrigacao_adicional>0 AND (q.cotacao->>'regra' IS DISTINCT FROM 'reparcelamento47_cotacao_v3' OR op.resultado->>'regra' IS DISTINCT FROM 'reparcelamento47_v3' OR op.resultado->>'obrigacaoAdicional' IS DISTINCT FROM q.cotacao->>'obrigacaoAdicional')) THEN RAISE EXCEPTION '51 componente adicional47 versão/prova inválida' USING ERRCODE='23514';END IF;
 IF op.resultado IS NULL OR op.hash_request IS DISTINCT FROM private47.hash(op.request) OR op.hash_auditoria IS DISTINCT FROM private47.hash(op.auditoria) OR op.auditoria->'request' IS DISTINCT FROM op.request OR op.auditoria->'resultado' IS DISTINCT FROM op.resultado OR op.auditoria->'cotacao' IS DISTINCT FROM q.cotacao OR q.hash_cotacao IS DISTINCT FROM private47.hash(q.cotacao) OR op.request->>'cotacaoHash' IS DISTINCT FROM q.hash_cotacao OR op.request->>'estadoHash' IS DISTINCT FROM q.cotacao->>'estadoHash' OR op.user_id<>ch.user_id OR op.resultado->>'operationId' IS DISTINCT FROM op.id::text OR op.resultado->>'contratoId' IS DISTINCT FROM ch.sucessor_id::text OR ch.saldo_transferido IS DISTINCT FROM (q.cotacao->>'saldoDevedor')::numeric OR ch.principal_original IS DISTINCT FROM (q.cotacao->>'principalOriginal')::numeric OR ch.juros_embutidos IS DISTINCT FROM (q.cotacao->>'jurosEmbutidos')::numeric THEN RAISE EXCEPTION '47 operação/prova divergente' USING ERRCODE='23514'; END IF;
 IF op.auditoria->'sucessor'->'contrato'->>'contrato_origem_id' IS DISTINCT FROM ch.origem_id::text OR (op.auditoria->'sucessor'->'contrato'->>'valor_principal')::numeric IS DISTINCT FROM ch.saldo_transferido OR (op.auditoria->'sucessor'->'contrato'->>'total_contrato')::numeric IS DISTINCT FROM (q.cotacao->>'totalNovo')::numeric OR op.auditoria->'sucessor'->'ledger' IS DISTINCT FROM '[]'::jsonb OR op.auditoria->'sucessor'->'origem' IS DISTINCT FROM 'null'::jsonb OR op.auditoria->'sucessor'->'renovacoes' IS DISTINCT FROM '[]'::jsonb OR jsonb_array_length(op.auditoria->'sucessor'->'parcelas') IS DISTINCT FROM jsonb_array_length(q.cotacao->'parcelas') THEN RAISE EXCEPTION '47 sucessor saldo/proveniência inválido' USING ERRCODE='23514'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(q.cotacao->'parcelas') LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(op.auditoria->'sucessor'->'parcelas') p WHERE p->>'numero'=v->>'numero' AND (p->>'valor_original')::numeric=(v->>'valor')::numeric AND (p->>'valor_juros')::numeric=(v->>'juros')::numeric AND p->>'data_vencimento'=v->>'vencimento' AND (p->>'valor_pago')::numeric=0 AND (p->>'saldo_residual')::numeric=0 AND p->'data_pagamento'='null'::jsonb) THEN RAISE EXCEPTION '47 agenda sucessora não equivale simulação' USING ERRCODE='23514'; END IF;
 END LOOP;
 SELECT auditoria->'depois' INTO STRICT old35 FROM public.multimodal_operacoes WHERE id=ch.origem_operation_id AND family='multimodal_criar' AND user_id=ch.user_id;
 PERFORM private47.estado_auditado(ch.user_id,ch.origem_id,a);
 IF old35->'origem' IS DISTINCT FROM a->'origem' OR a->'origem' IS DISTINCT FROM (SELECT to_jsonb(o) FROM public.multimodal_origens o WHERE contrato_id=ch.origem_id) OR a->'ledger' IS DISTINCT FROM b->'ledger' OR a->'origem' IS DISTINCT FROM b->'origem' OR a->'renovacoes' IS DISTINCT FROM b->'renovacoes' OR ((a->'contrato')-ARRAY['status','updatedAt']) IS DISTINCT FROM ((b->'contrato')-ARRAY['status','updatedAt']) OR b->'contrato'->>'status'<>'cancelado' OR jsonb_array_length(a->'parcelas')<>jsonb_array_length(b->'parcelas') THEN RAISE EXCEPTION '47 preservação da origem25 divergente' USING ERRCODE='23514'; END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(a->'parcelas') LOOP
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'parcelas') p WHERE p-'status'-'updatedAt'=v-'status'-'updatedAt' AND p->>'status'='cancelada') THEN RAISE EXCEPTION '47 parcela original adulterada' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF public.multimodal_snapshot(ch.origem_id) IS DISTINCT FROM b THEN RAISE EXCEPTION '47 origem encerrada divergente' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION obrigacoes51.validar44_base(uid integer,cid integer,s jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE  c jsonb; p jsonb; op jsonb; n integer; i integer:=0; juros numeric; total numeric; ref numeric; jr numeric;
BEGIN
 PERFORM public.caixa37_verificar();
 IF uid IS NULL OR uid<=0 OR cid IS NULL OR cid<=0 OR NOT EXISTS(SELECT 1 FROM public.contratos WHERE id=cid AND user_id=uid) THEN RAISE EXCEPTION 'Contrato44 indisponível' USING ERRCODE='42501'; END IF;
 -- NÃO adota legado, multimodal, multas ou recebimentos/renovações pré-existentes.
 IF NOT EXISTS(SELECT 1 FROM public.emprestimos_rpc_origens WHERE contrato_id=cid AND user_id=uid)
 OR EXISTS(SELECT 1 FROM public.multimodal_origens WHERE contrato_id=cid)
 OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid)
 OR EXISTS(SELECT 1 FROM public.legados_estados WHERE contrato_id=cid)
 OR EXISTS(SELECT 1 FROM public.ciclo_operacoes WHERE contrato_id=cid)
 OR EXISTS(SELECT 1 FROM public.renovacao_operacoes WHERE contrato_id=cid)
 THEN RAISE EXCEPTION 'Contrato44 fora do incremento sem pagamentos' USING ERRCODE='23514'; END IF;
 PERFORM public.multa36_vinculos(uid,cid);
 c:=s->'contrato';
 SELECT to_jsonb(o) INTO op FROM public.emprestimos_rpc_operacoes o JOIN public.emprestimos_rpc_origens r ON r.operacao_id=o.id WHERE r.contrato_id=cid;
 n:=(op->'payload'->>'numeroParcelas')::int;
 -- Além do selo atual, conservar a criação inteira, exceto os únicos campos de calendário.
 IF c-ARRAY['data_vencimento','data_vencimento_primeira','dia_vencimento','updatedAt'] IS DISTINCT FROM (op->'auditoria'->'contrato')-ARRAY['data_vencimento','data_vencimento_primeira','dia_vencimento','updatedAt']
 OR c->>'status' IS DISTINCT FROM 'ativo' OR c->>'modalidade' IS DISTINCT FROM 'mensal' OR c->>'tipo_taxa' IS DISTINCT FROM 'mensal'
 OR jsonb_array_length(s->'parcelas') IS DISTINCT FROM n OR n NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Criação44 não conservada' USING ERRCODE='23514'; END IF;
 -- O snapshot de criação usa contrato/parcelas; livro deve ter APENAS o débito comprovado.
 IF jsonb_array_length(s->'ledger')<>1 OR NOT EXISTS(SELECT 1 FROM public.emprestimos_rpc_origens o JOIN public.transacoes_caixa t ON t.id=o.transacao_caixa_id WHERE o.contrato_id=cid AND t.contrato_id=cid AND t.user_id=uid AND t.parcela_id IS NULL AND t.tipo='saida' AND t.categoria='emprestimo_liberado' AND t.valor=(c->>'valor_principal')::numeric AND t.conta_caixa_id=(c->>'conta_caixa_id')::int AND t.data_transacao=(c->>'data_inicio')::date) THEN RAISE EXCEPTION 'Livro44 não é apenas desembolso' USING ERRCODE='23514'; END IF;
 juros:=round((c->>'valor_principal')::numeric*(c->>'taxa_juros')::numeric/100*n,2); total:=(c->>'valor_principal')::numeric+juros; ref:=round(total/n,2); jr:=round(juros/n,2);
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') LOOP
 i:=i+1;
 IF p-ARRAY['data_vencimento','status','updatedAt'] IS DISTINCT FROM (op->'auditoria'->'parcelas'->(i-1))-ARRAY['data_vencimento','status','updatedAt']
 OR (p->>'numero')::int IS DISTINCT FROM i OR (p->>'numero_parcela')::int IS DISTINCT FROM i
 OR (p->>'valor')::numeric IS DISTINCT FROM (CASE WHEN i=n THEN total-ref*(n-1) ELSE ref END)
 OR (p->>'valor_original')::numeric IS DISTINCT FROM (p->>'valor')::numeric
 OR (p->>'valor_juros')::numeric IS DISTINCT FROM (CASE WHEN i=n THEN juros-jr*(n-1) ELSE jr END)
 OR p->>'status' NOT IN('pendente','atrasada','vencendo_hoje') OR (p->>'valor_pago')::numeric IS DISTINCT FROM 0::numeric
 OR (p->>'saldo_residual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'valor_multa')::numeric IS DISTINCT FROM 0::numeric
 OR (p->>'multa_manual')::numeric IS DISTINCT FROM 0::numeric OR (p->>'multa_diaria_usada')::numeric IS DISTINCT FROM 0::numeric
 OR p->'data_pagamento' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Parcela44 não conservada' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN s;
END $$;
CREATE OR REPLACE FUNCTION manutencao44.validar(uid integer,cid integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$ DECLARE s jsonb;BEGIN s:=public.ciclo_validar(uid,cid);IF EXISTS(SELECT 1 FROM obrigacoes51.operacoes WHERE contrato_id=cid AND user_id=uid AND resultado IS NOT NULL AND request->'proposta'->>'acao'='editar' LIMIT 1) THEN RETURN obrigacoes51.replay21(uid,cid,s);END IF;RETURN obrigacoes51.validar44_base(uid,cid,s);END $$;
CREATE FUNCTION obrigacoes51.cotacao(uid integer,cid integer,v jsonb,instante timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE b jsonb;s jsonb;plan jsonb;q jsonb;p jsonb;source text;a text;pid integer;ids integer[]:='{}';due numeric:=0;val numeric;total numeric;additional numeric;day date:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;dest integer;anycancel boolean;
BEGIN
 PERFORM obrigacoes51.verificar();v:=obrigacoes51.proposta(v);PERFORM obrigacoes51.travar(uid,cid);b:=obrigacoes51.base(uid,cid);s:=b->'financeiro';source:=b->>'origemTipo';a:=v->>'acao';total:=(s->'contrato'->>'total_contrato')::numeric;plan:=jsonb_build_object('totalContrato',total::numeric(12,2)::text);
 IF jsonb_array_length(s->'parcelas') NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION '51 conjunto1..60 íntegro necessário' USING ERRCODE='54000';END IF;
 anycancel:=b->'encerramento' IS DISTINCT FROM 'null'::jsonb OR jsonb_array_length(b->'cancelamentos')>0;
 IF a IN('adicionar','editar') AND anycancel THEN RAISE EXCEPTION '51 conjunto renunciado não pode ser reprecificado/adicionado' USING ERRCODE='23514';END IF;
 IF a='adicionar' THEN
 IF source<>'multimodal35' THEN RAISE EXCEPTION '51 append inicial somente raiz35 genuína' USING ERRCODE='0A000';END IF;
 s:=obrigacoes51.validar_mensal(uid,cid);PERFORM private47.estado_auditado(uid,cid,s);plan:=obrigacoes51.plano(s,v,instante);ids:='{}'::integer[];
 ELSIF a='editar' THEN
 IF source NOT IN('multimodal35','prospectivo21') THEN RAISE EXCEPTION '51 edição requer origem35/21 comprovada, não legado presumido' USING ERRCODE='0A000';END IF;
 IF source='multimodal35' THEN s:=obrigacoes51.validar_mensal(uid,cid);ELSE
 IF NOT EXISTS(SELECT 1 FROM public.ciclo_estados WHERE contrato_id=cid AND user_id=uid AND origem_completa LIMIT 1) THEN RAISE EXCEPTION '51 edição21 requer estado completo genuíno' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.renovacao_operacoes WHERE contrato_id=cid LIMIT 1) OR EXISTS(SELECT 1 FROM public.multa36_origens WHERE contrato_id=cid LIMIT 1) THEN RAISE EXCEPTION '51 edição21 não renovada/multa' USING ERRCODE='0A000';END IF;END IF;
 plan:=obrigacoes51.plano(s,v,instante);pid:=obrigacoes51.id(v->'parcelaId');ids:=ARRAY[pid];
 ELSIF a IN('cancelar','arquivar') THEN
 IF s->'contrato'->>'status' IN('renegociado') OR EXISTS(SELECT 1 FROM public.contratos WHERE contrato_origem_id=cid LIMIT 1) THEN RAISE EXCEPTION '51 obrigação transferida: atuar no sucessor exigível' USING ERRCODE='0A000';END IF;
 IF v->'alvo'->>'tipo'='parcela' THEN pid:=obrigacoes51.id(v->'alvo'->'parcelaId');IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'parcelas') j WHERE (j->>'id')::int=pid) THEN RAISE EXCEPTION '51 alvo indisponível' USING ERRCODE='42501';END IF;END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'id')::int LOOP
 IF pid IS NULL OR (p->>'id')::int=pid THEN
 val:=obrigacoes51.registrada(p);IF anycancel AND (b->'encerramento' IS DISTINCT FROM 'null'::jsonb OR EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=(p->>'id')::int LIMIT 1)) THEN val:=0;END IF;
 IF a='cancelar' AND val>0 THEN ids:=array_append(ids,(p->>'id')::int);due:=due+val;
 ELSIF a='arquivar' THEN IF val>0 THEN RAISE EXCEPTION '51 somente histórico encerrado pode ser arquivado' USING ERRCODE='23514';END IF;ids:=array_append(ids,(p->>'id')::int);END IF;
 END IF;END LOOP;
 IF a='arquivar' AND EXISTS(SELECT 1 FROM obrigacoes51.arquivos WHERE contrato_id=cid AND parcela_id IS NOT DISTINCT FROM pid LIMIT 1) THEN RAISE EXCEPTION '51 histórico já arquivado' USING ERRCODE='22023';END IF;
 ELSIF a='quitar' THEN
 dest:=obrigacoes51.id(v->'contaCaixaId');
 IF dest IS DISTINCT FROM (s->'contrato'->>'conta_caixa_id')::int THEN RAISE EXCEPTION '51 escolha explícita deve corresponder à conta vinculada neste recorte; jamais default silencioso' USING ERRCODE='0A000';END IF;
 PERFORM public.caixa37_validar_livro(uid);
 IF NOT EXISTS(SELECT 1 FROM public.contas_caixa WHERE id=dest AND user_id=uid AND ativo LIMIT 1) THEN RAISE EXCEPTION '51 conta destino própria ativa obrigatória' USING ERRCODE='42501';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') ORDER BY (value->>'id')::int LOOP
 IF obrigacoes51.registrada(p)>0 AND NOT EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=(p->>'id')::int LIMIT 1) AND b->'encerramento'='null'::jsonb THEN
 IF source='multimodal35' THEN q:=public.multimodal_cotacao(uid,cid,(p->>'id')::int,instante);
 ELSIF source='prospectivo21' THEN q:=public.ciclo_cotacao(uid,cid,(p->>'id')::int);
 ELSE q:=public.legados_validar(uid,cid,(p->>'id')::int,dest);END IF;
 IF q->'elegivel' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION '51 título não elegível à baixa real' USING ERRCODE='23514';END IF;
 due:=due+(q->>'totalExigido')::numeric;ids:=array_append(ids,(p->>'id')::int);
 END IF;END LOOP;
 IF due IS DISTINCT FROM obrigacoes51.dinheiro(v->>'valorRecebido') THEN RAISE EXCEPTION '51 dinheiro real informado deve igualar exigibilidade cotada; sem quitação presumida/desconto implícito' USING ERRCODE='22023';END IF;
 END IF;
 IF (cardinality(ids)=0 AND a<>'adicionar') OR NOT public.multimodal_moeda(due) THEN RAISE EXCEPTION '51 sem obrigação/alvo/delta ou valor fora faixa' USING ERRCODE='22023';END IF;
 SELECT coalesce(sum(valor),0) INTO additional FROM obrigacoes51.adicionais WHERE contrato_id=cid;
 RETURN jsonb_build_object('versao','obrigacoes51_v1','userId',uid,'contratoId',cid,'proposta',v,'origem',source,'estadoHash',obrigacoes51.hash(jsonb_build_object('base',b,'dia',day)),'dataCalculo',day,'totalAntes',total::numeric(12,2)::text,'totalDepois',plan->>'totalContrato','obrigacaoAdicional',(additional+CASE WHEN a='adicionar' THEN (v->>'valor')::numeric ELSE 0 END)::numeric(12,2)::text,'valorExigido',CASE WHEN a='quitar' THEN due::numeric(12,2)::text ELSE '0.00' END,'contaDestinoId',dest,'idsAfetados',ids,'caixaPreservado',a<>'quitar');
END $$;
CREATE FUNCTION obrigacoes51.fechar(uid integer,k uuid,r jsonb,oid51 uuid,res jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT jsonb_build_object('status','confirmed','sameIntentOnly',true,'versao','obrigacoes51_v1','userId',uid,'idempotencyKey',k,'request',r,'resultado',res)
$$;
CREATE FUNCTION obrigacoes51.executar(uid integer,k uuid,req jsonb,recovery boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET TimeZone='UTC' AS $$
DECLARE r jsonb;v jsonb;q jsonb;b jsonb;afterb jsonb;s jsonb;plan jsonb;expected jsonb;p jsonb;np jsonb;h jsonb;res jsonb;closed jsonb;old obrigacoes51.operacoes%ROWTYPE;f obrigacoes51.fences%ROWTYPE;mop public.multimodal_operacoes%ROWTYPE;oid51 uuid;cid integer;pid integer;dest integer;ids integer[];a text;source text;instante timestamptz;day date;subkey uuid;subq jsonb;receipt jsonb;sumcash numeric:=0;oldledger jsonb;newledger jsonb;
BEGIN
 PERFORM obrigacoes51.verificar();r:=obrigacoes51.request(req);v:=r->'proposta';cid:=(r->>'contratoId')::int;a:=v->>'acao';IF uid IS NULL OR uid<=0 OR k IS NULL THEN RAISE EXCEPTION '51 owner/UUID obrigatórios' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('obrigacoes51:'||uid::text||':'||k::text,51));
 -- Exact committed proof is replayed BEFORE current eligibility; no DML, no fence fabricated.
 SELECT * INTO old FROM obrigacoes51.operacoes WHERE user_id=uid AND chave=k LIMIT 1;
 IF FOUND THEN
 IF old.request IS DISTINCT FROM r OR old.hash_request IS DISTINCT FROM obrigacoes51.hash(r) THEN RAISE EXCEPTION '51 UUID request divergente' USING ERRCODE='23505';END IF;
 IF old.resultado IS NULL OR old.hash_resultado IS DISTINCT FROM obrigacoes51.hash(old.resultado) THEN RAISE EXCEPTION '51 prova incompleta/corrompida' USING ERRCODE='23514';END IF;RETURN old.resultado;END IF;
 PERFORM obrigacoes51.travar(uid,cid);
 SELECT * INTO f FROM obrigacoes51.fences WHERE user_id=uid AND chave=k LIMIT 1;
 IF FOUND THEN
 IF f.request IS DISTINCT FROM r OR f.hash_request IS DISTINCT FROM obrigacoes51.hash(r) THEN RAISE EXCEPTION '51 fence request divergente' USING ERRCODE='23505';END IF;
 IF NOT recovery THEN RAISE EXCEPTION '51 UUID fenced terminal' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('status','fenced','sameIntentOnly',true,'versao','obrigacoes51_v1','userId',uid,'idempotencyKey',k,'request',r);END IF;
 IF recovery THEN
 INSERT INTO obrigacoes51.fences(user_id,chave,contrato_id,request,hash_request) VALUES(uid,k,cid,r,obrigacoes51.hash(r));RETURN jsonb_build_object('status','fenced','sameIntentOnly',true,'versao','obrigacoes51_v1','userId',uid,'idempotencyKey',k,'request',r);END IF;
 instante:=clock_timestamp();day:=(instante AT TIME ZONE 'America/Sao_Paulo')::date;q:=obrigacoes51.cotacao(uid,cid,v,instante);
 IF q->>'estadoHash' IS DISTINCT FROM r->>'estadoHash' OR q->>'dataCalculo' IS DISTINCT FROM r->>'dataCalculo' THEN RAISE EXCEPTION '51 cotação/estado/BRT expirou' USING ERRCODE='40001';END IF;
 b:=obrigacoes51.base(uid,cid);s:=b->'financeiro';source:=b->>'origemTipo';SELECT array_agg(j::int ORDER BY ord) INTO ids FROM jsonb_array_elements_text(q->'idsAfetados') WITH ORDINALITY x(j,ord);
 INSERT INTO obrigacoes51.operacoes(user_id,chave,contrato_id,request,hash_request,antes) VALUES(uid,k,cid,r,obrigacoes51.hash(r),b) RETURNING id INTO oid51;
 IF a IN('adicionar','editar') THEN
 IF source='multimodal35' THEN
 -- A closed action on existing48 protocol, not a fictitious receiving family.
 res:=manutencao48.executar(uid,k,cid,obrigacoes51.hash(s),v,r->>'motivo');
 IF a='adicionar' THEN SELECT array_agg(parcela_id) INTO ids FROM obrigacoes51.adicionais WHERE operacao48=(res->>'operationId')::uuid;END IF;
 ELSE
 plan:=obrigacoes51.plano(s,v,instante);expected:=s;PERFORM public.ciclo_autorizar('receber',(s->'contrato'->>'conta_caixa_id')::int,cid);
 FOR p IN SELECT value FROM jsonb_array_elements(s->'parcelas') LOOP
 SELECT value INTO STRICT np FROM jsonb_array_elements(plan->'parcelas') WHERE value->'id'=p->'id';
 IF np IS DISTINCT FROM p THEN
 UPDATE public.parcelas SET valor=(np->>'valor')::numeric,valor_original=(np->>'valor_original')::numeric,valor_juros=(np->>'valor_juros')::numeric,data_vencimento=(np->>'data_vencimento')::date,"updatedAt"=instante WHERE id=(p->>'id')::int AND contrato_id=cid AND user_id=uid;
 IF NOT FOUND OR (SELECT to_jsonb(x) FROM public.parcelas x WHERE id=(p->>'id')::int LIMIT 1) IS DISTINCT FROM np THEN RAISE EXCEPTION '51 edição21 readback alvo divergente' USING ERRCODE='23514';END IF;END IF;END LOOP;
 UPDATE public.contratos SET total_contrato=(plan->'contrato'->>'total_contrato')::numeric,valor_parcela=(plan->'contrato'->>'valor_parcela')::numeric,data_vencimento_primeira=(plan->'contrato'->>'data_vencimento_primeira')::date,data_vencimento=(plan->'contrato'->>'data_vencimento')::date,dia_vencimento=(plan->'contrato'->>'dia_vencimento')::int,"updatedAt"=instante WHERE id=cid AND user_id=uid;
 INSERT INTO public.contrato_historico(contrato_id,user_id,tipo,descricao,created_at) VALUES(cid,uid::text,'edicao_parcela','Edição51 '||oid51::text||': '||(r->>'motivo'),instante) RETURNING to_jsonb(contrato_historico) INTO h;
 expected:=jsonb_set(jsonb_set(expected,'{contrato}',plan->'contrato'),'{parcelas}',(SELECT jsonb_agg(j ORDER BY (j->>'numero')::int,(j->>'id')::int) FROM jsonb_array_elements(plan->'parcelas') j));expected:=jsonb_set(expected,'{historico}',s->'historico'||jsonb_build_array(h));
 IF public.ciclo_snapshot(cid) IS DISTINCT FROM expected THEN RAISE EXCEPTION '51 edição21 snapshot/delta integral divergente' USING ERRCODE='23514';END IF;
 UPDATE public.ciclo_estados SET snapshot=expected WHERE contrato_id=cid AND user_id=uid AND origem_completa;IF NOT FOUND THEN RAISE EXCEPTION '51 estado21 predecessor ausente' USING ERRCODE='23514';END IF;DELETE FROM public.ciclo_autorizacoes ca WHERE ca.xid=txid_current() AND ca.pid=pg_backend_pid();PERFORM public.ciclo_validar(uid,cid);
 END IF;
 ELSIF a='cancelar' THEN
 FOREACH pid IN ARRAY ids LOOP SELECT to_jsonb(x) INTO STRICT p FROM public.parcelas x WHERE id=pid AND contrato_id=cid LIMIT 1;INSERT INTO obrigacoes51.cancelamentos VALUES(uid,cid,pid,oid51,obrigacoes51.registrada(p),(p->>'valor_pago')::numeric,p->>'status');END LOOP;
 IF v->'alvo'->>'tipo'='contrato' THEN INSERT INTO obrigacoes51.encerramentos VALUES(uid,cid,oid51);END IF;
 ELSIF a='arquivar' THEN
 INSERT INTO obrigacoes51.arquivos VALUES(uid,cid,CASE WHEN v->'alvo'->>'tipo'='parcela' THEN (v->'alvo'->>'parcelaId')::int ELSE NULL END,oid51);
 ELSIF a='quitar' THEN
 dest:=(v->>'contaCaixaId')::int;
 FOREACH pid IN ARRAY ids LOOP
 -- All calls stay inside THIS transaction. Sequential hash recotation never crosses APP/network.
 subkey:=gen_random_uuid();
 IF source='multimodal35' THEN subq:=public.multimodal_cotacao(uid,cid,pid,instante);receipt:=public.rpc_receber_emprestimo_multimodal(uid,subkey,cid,pid,(subq->>'totalExigido')::numeric,(subq->>'totalExigido')::numeric,day,subq->>'estadoHash','integral','Quitação51 dinheiro real '||oid51::text);
 ELSIF source='prospectivo21' THEN subq:=public.ciclo_cotacao(uid,cid,pid);receipt:=public.rpc_receber_emprestimo_prospectivo(uid,subkey,cid,pid,(subq->>'totalExigido')::numeric,(subq->>'totalExigido')::numeric,day,subq->>'estadoHash','integral','Quitação51 dinheiro real '||oid51::text);
 ELSE subq:=public.legados_validar(uid,cid,pid,dest);receipt:=public.rpc_receber_legado(uid,subkey,cid,pid,dest,subq->>'totalExigido',subq->>'totalExigido',day,subq->>'estadoHash',subq->>'regra','Quitação51 dinheiro real '||oid51::text);END IF;
 sumcash:=sumcash+(subq->>'totalExigido')::numeric;
 END LOOP;
 IF sumcash IS DISTINCT FROM (v->>'valorRecebido')::numeric THEN RAISE EXCEPTION '51 soma de baixas não equivale dinheiro real informado' USING ERRCODE='23514';END IF;
 END IF;
 afterb:=obrigacoes51.base(uid,cid);
 IF a IN('cancelar','arquivar') AND (afterb->'financeiro' IS DISTINCT FROM b->'financeiro' OR afterb->'conta' IS DISTINCT FROM b->'conta' OR afterb->'livroConta' IS DISTINCT FROM b->'livroConta') THEN RAISE EXCEPTION '51 renúncia/arquivo não muda base nem Caixa' USING ERRCODE='23514';END IF;
 IF a IN('adicionar','editar') AND (afterb->'financeiro'->'ledger' IS DISTINCT FROM b->'financeiro'->'ledger' OR afterb->'conta' IS DISTINCT FROM b->'conta' OR afterb->'livroConta' IS DISTINCT FROM b->'livroConta') THEN RAISE EXCEPTION '51 manutenção não movimenta Caixa' USING ERRCODE='23514';END IF;
 IF a='quitar' THEN
 SELECT coalesce(sum(t.valor),0) INTO sumcash FROM public.transacoes_caixa t WHERE t.contrato_id=cid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'financeiro'->'ledger') oldt WHERE (oldt->>'id')::int=t.id);
 IF sumcash IS DISTINCT FROM (v->>'valorRecebido')::numeric OR EXISTS(SELECT 1 FROM public.transacoes_caixa t WHERE t.contrato_id=cid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'financeiro'->'ledger') oldt WHERE (oldt->>'id')::int=t.id) AND (t.tipo IS DISTINCT FROM 'entrada' OR t.user_id IS DISTINCT FROM uid OR t.conta_caixa_id IS DISTINCT FROM dest OR t.parcela_id IS NULL OR NOT(t.parcela_id=ANY(ids)))) OR EXISTS(SELECT 1 FROM public.parcelas WHERE id=ANY(ids) AND (status IS DISTINCT FROM 'paga' OR saldo_residual IS DISTINCT FROM 0::numeric OR data_pagamento IS DISTINCT FROM day)) THEN RAISE EXCEPTION '51 quitação requer entradas reais e baixas integrais atômicas próprias' USING ERRCODE='23514';END IF;
 END IF;
 IF (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date IS DISTINCT FROM day THEN RAISE EXCEPTION '51 virada civil BRT, rollback inteiro' USING ERRCODE='40001';END IF;
 res:=jsonb_build_object('operationId',oid51,'contratoId',cid,'acao',a,'idsAfetados',ids,'valorRecebido',CASE WHEN a='quitar' THEN v->>'valorRecebido' ELSE '0.00' END,'contaDestinoId',dest,'caixaPreservado',a<>'quitar');closed:=obrigacoes51.fechar(uid,k,r,oid51,res);
 UPDATE obrigacoes51.operacoes SET depois=afterb,resultado=closed,hash_resultado=obrigacoes51.hash(closed),concluida_em=clock_timestamp() WHERE id=oid51;RETURN closed;
END $$;
CREATE FUNCTION obrigacoes51.guardar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE oldj jsonb;newj jsonb;cid integer;pid integer;closed boolean;renounced boolean;
BEGIN
 IF TG_OP<>'INSERT' THEN oldj:=to_jsonb(OLD);END IF;IF TG_OP<>'DELETE' THEN newj:=to_jsonb(NEW);END IF;
 IF TG_TABLE_NAME='contratos' THEN
 cid:=coalesce((oldj->>'id')::int,(newj->>'id')::int);
 IF newj->'contrato_origem_id' IS DISTINCT FROM 'null'::jsonb AND EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE contrato_id=(newj->>'contrato_origem_id')::int LIMIT 1) THEN RAISE EXCEPTION '51 saldo renunciado não pode ser transferido/renovado' USING ERRCODE='23514';END IF;
 ELSE cid:=coalesce((oldj->>'contrato_id')::int,(newj->>'contrato_id')::int);END IF;
 IF cid IS NOT NULL THEN
 -- Guards never wait out of financial lock order. Genuine writers already hold these locks.
 IF NOT pg_try_advisory_xact_lock(34035,cid) THEN RAISE EXCEPTION '51 obrigação concorrente' USING ERRCODE='40001';END IF;
 closed:=EXISTS(SELECT 1 FROM obrigacoes51.encerramentos WHERE contrato_id=cid LIMIT 1);
 ELSE closed:=false;END IF;
 IF TG_TABLE_NAME='parcelas' THEN
 pid:=coalesce((oldj->>'id')::int,(newj->>'id')::int);renounced:=EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=pid LIMIT 1);
 IF (closed OR renounced) AND (TG_OP IN('INSERT','DELETE') OR oldj IS DISTINCT FROM newj) THEN RAISE EXCEPTION '51 obrigação renunciada não pode receber/reabrir/revincular' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='transacoes_caixa' THEN
 pid:=coalesce((newj->>'parcela_id')::int,(oldj->>'parcela_id')::int);
 IF TG_OP='INSERT' AND (closed OR EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos WHERE parcela_id=pid LIMIT 1)) THEN RAISE EXCEPTION '51 obrigação renunciada não recebe dinheiro novo' USING ERRCODE='23514';END IF;
 ELSIF TG_TABLE_NAME='contratos' THEN
 IF closed AND (TG_OP='DELETE' OR (TG_OP='UPDATE' AND oldj IS DISTINCT FROM newj)) THEN RAISE EXCEPTION '51 contrato integralmente renunciado é inexigível, sem reabertura' USING ERRCODE='23514';END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;
CREATE TRIGGER obrigacoes51_guard BEFORE INSERT OR UPDATE OR DELETE ON public.contratos FOR EACH ROW EXECUTE FUNCTION obrigacoes51.guardar();
CREATE TRIGGER obrigacoes51_guard BEFORE INSERT OR UPDATE OR DELETE ON public.parcelas FOR EACH ROW EXECUTE FUNCTION obrigacoes51.guardar();
CREATE TRIGGER obrigacoes51_guard BEFORE INSERT OR UPDATE OR DELETE ON public.transacoes_caixa FOR EACH ROW EXECUTE FUNCTION obrigacoes51.guardar();
CREATE FUNCTION obrigacoes51.imutavel() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF TG_TABLE_NAME='operacoes' AND TG_OP='UPDATE' THEN
 IF to_jsonb(OLD)->'resultado'='null'::jsonb AND to_jsonb(NEW)->'resultado'<>'null'::jsonb AND pg_xact_status(OLD.xmin::text::xid8)='in progress' AND (to_jsonb(OLD)-ARRAY['depois','resultado','hash_resultado','concluida_em']) IS NOT DISTINCT FROM (to_jsonb(NEW)-ARRAY['depois','resultado','hash_resultado','concluida_em']) THEN RETURN NEW;END IF;END IF;
 RAISE EXCEPTION '51 trilha imutável; sem UPDATE/DELETE/TRUNCATE' USING ERRCODE='42501';
END $$;
CREATE FUNCTION obrigacoes51.commit_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE op obrigacoes51.operacoes%ROWTYPE;
BEGIN
 SELECT * INTO STRICT op FROM obrigacoes51.operacoes WHERE id=NEW.id LIMIT 1;
 IF op.resultado IS NULL OR op.concluida_em IS NULL OR op.depois IS NULL OR op.hash_request IS DISTINCT FROM obrigacoes51.hash(op.request) OR op.hash_resultado IS DISTINCT FROM obrigacoes51.hash(op.resultado) OR op.resultado->'request' IS DISTINCT FROM op.request OR op.resultado->>'userId' IS DISTINCT FROM op.user_id::text OR op.resultado->>'idempotencyKey' IS DISTINCT FROM op.chave::text OR op.resultado->'resultado'->>'operationId' IS DISTINCT FROM op.id::text OR EXISTS(SELECT 1 FROM public.ciclo_autorizacoes WHERE xid=txid_current() AND pid=pg_backend_pid() LIMIT 1) OR EXISTS(SELECT 1 FROM public.multimodal_autorizacoes WHERE xid=txid_current() AND pid=pg_backend_pid() LIMIT 1) THEN RAISE EXCEPTION '51 commit incompleto/capacidade residual/prova divergente' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM obrigacoes51.cancelamentos x LEFT JOIN public.parcelas p ON p.id=x.parcela_id WHERE x.operacao_id=op.id AND (x.user_id IS DISTINCT FROM op.user_id OR p.user_id IS DISTINCT FROM x.user_id OR p.contrato_id IS DISTINCT FROM x.contrato_id OR x.contrato_id IS DISTINCT FROM op.contrato_id) LIMIT 1) THEN RAISE EXCEPTION '51 evento vínculo divergente' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER commit51 AFTER INSERT OR UPDATE ON obrigacoes51.operacoes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION obrigacoes51.commit_check();
DO $$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['manifesto','operacoes','fences','adicionais','cancelamentos','encerramentos','arquivos'] LOOP
 EXECUTE format('ALTER TABLE obrigacoes51.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON obrigacoes51.%I FROM PUBLIC,anon,authenticated,service_role',t);
 IF t<>'manifesto' THEN EXECUTE format('CREATE TRIGGER imutavel51 BEFORE UPDATE OR DELETE ON obrigacoes51.%I FOR EACH ROW EXECUTE FUNCTION obrigacoes51.imutavel()',t);EXECUTE format('CREATE TRIGGER imutavel51_truncate BEFORE TRUNCATE ON obrigacoes51.%I FOR EACH STATEMENT EXECUTE FUNCTION obrigacoes51.imutavel()',t);END IF;
 END LOOP;
END $$;
CREATE FUNCTION obrigacoes51.metadata() RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT obrigacoes51.hash(jsonb_build_object(
 'schema',(SELECT to_jsonb(n) FROM pg_namespace n WHERE nspname='obrigacoes51'),
 'functions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_proc p WHERE pronamespace='obrigacoes51'::regnamespace OR (pronamespace='public'::regnamespace AND proname IN('rpc_cotar_obrigacoes51','rpc_executar_obrigacoes51','rpc_conferir_obrigacoes51','rpc_estado_obrigacoes51','rpc_capacidade_obrigacoes51'))),
 'relations',(SELECT jsonb_agg(to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid'] ORDER BY c.oid) FROM pg_class c WHERE c.relnamespace='obrigacoes51'::regnamespace),
 'attributes',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attrelid,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid WHERE c.relnamespace='obrigacoes51'::regnamespace),
 'constraints',(SELECT jsonb_agg(to_jsonb(k) ORDER BY k.oid) FROM pg_constraint k WHERE connamespace='obrigacoes51'::regnamespace),
 'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d JOIN pg_class c ON c.oid=d.adrelid WHERE c.relnamespace='obrigacoes51'::regnamespace),
 'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid WHERE c.relnamespace='obrigacoes51'::regnamespace),
 'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='obrigacoes51'::regnamespace OR t.tgname='obrigacoes51_guard'),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace='obrigacoes51'::regnamespace)));
$$;
CREATE FUNCTION obrigacoes51.verificar() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 PERFORM public.legados_verificar();PERFORM public.multimodal_verificar();PERFORM public.multa36_verificar();PERFORM public.caixa37_verificar();PERFORM manutencao44.verificar();PERFORM caixa_manutencao45.verificar();PERFORM calendario46.verificar();PERFORM private47.verificar();PERFORM manutencao48.verificar();PERFORM despesas49.verificar();
 IF (SELECT assinatura FROM obrigacoes51.manifesto WHERE id=1 LIMIT 1) IS DISTINCT FROM obrigacoes51.metadata() THEN RAISE EXCEPTION '51 metadata incompatível; nunca reseal runtime' USING ERRCODE='55000';END IF;
END $$;
