CREATE FUNCTION public.rpc_capacidade_obrigacoes51() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ BEGIN PERFORM obrigacoes51.verificar();RETURN jsonb_build_object('versao','obrigacoes51_v1','disponivel',true);END $$;
DO $$ DECLARE p record;BEGIN
 FOR p IN SELECT pp.oid,n.nspname,pp.proname,pg_get_function_identity_arguments(pp.oid) args FROM pg_proc pp JOIN pg_namespace n ON n.oid=pp.pronamespace WHERE n.nspname='obrigacoes51' OR (n.nspname='public' AND pp.proname IN('rpc_cotar_obrigacoes51','rpc_executar_obrigacoes51','rpc_conferir_obrigacoes51','rpc_estado_obrigacoes51','rpc_capacidade_obrigacoes51')) LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %I.%I(%s) FROM PUBLIC,anon,authenticated,service_role',p.nspname,p.proname,p.args);
 IF p.nspname='public' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %I.%I(%s) TO service_role',p.nspname,p.proname,p.args);END IF;
 END LOOP;
END $$;
