,{"namespace":"obrigacoes51","name":"moeda_leitura","bodyHash":"e1aa796fcba97654b7075faf798708c0222ba3f2081b75d2e7ae96c64ce550fb","config":["search_path=pg_catalog, pg_temp"],"secdef":true,"sourceHash":"234f0b8c0bb4059812414cbadd2c833a9ca23a6d784d23cf4571a41a23b294c4"}]'::jsonb) LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=e->>'namespace' AND p.proname=e->>'name' AND p.proowner=(SELECT oid FROM pg_roles WHERE rolname='postgres' LIMIT 1) AND p.prosecdef=(e->>'secdef')::boolean AND to_jsonb(p.proconfig)=e->'config' AND encode(extensions.digest(p.prosrc,'sha256'),'hex')=e->>'bodyHash' AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND has_function_privilege('service_role',p.oid,'EXECUTE')=(n.nspname='public' AND p.proname LIKE 'rpc_%') LIMIT 1) THEN RAISE EXCEPTION '51 successor source/config/ACL divergente %.%',e->>'namespace',e->>'name' USING ERRCODE='55000';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM witness51_functions w LEFT JOIN pg_proc p ON p.oid=w.oid JOIN pg_namespace n ON n.oid=p.pronamespace WHERE CASE WHEN n.nspname||'.'||p.proname=ANY(ARRAY['manutencao48.proposta','manutencao48.validar','manutencao48.plano','manutencao48.executar','calendario46.validar','private47.estado_auditado','private47.cotar','private47.executar','private47.validar_op','manutencao44.validar']) THEN to_jsonb(p)-'prosrc' IS DISTINCT FROM w.snapshot-'prosrc' ELSE to_jsonb(p) IS DISTINCT FROM w.snapshot END LIMIT 1) THEN RAISE EXCEPTION '51 função antiga alterada fora allowlist prosrc exata' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM witness51_relations w LEFT JOIN pg_class c ON c.oid=w.oid WHERE CASE WHEN w.oid='private47.cadeia'::regclass THEN (to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid','relnatts','relchecks']) IS DISTINCT FROM (w.snapshot-ARRAY['relnatts','relchecks']) OR c.relchecks IS DISTINCT FROM (w.snapshot->>'relchecks')::int+1 OR c.relnatts IS DISTINCT FROM (w.snapshot->>'relnatts')::int+1 ELSE (to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relallfrozen','relfrozenxid','relminmxid']) IS DISTINCT FROM w.snapshot END LIMIT 1) THEN RAISE EXCEPTION '51 relação predecessor alterada fora chainA1' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM witness51_attributes w LEFT JOIN pg_attribute a ON a.attrelid=w.attrelid AND a.attnum=w.attnum WHERE to_jsonb(a) IS DISTINCT FROM w.snapshot LIMIT 1) OR EXISTS(SELECT 1 FROM witness51_policies w LEFT JOIN pg_policy p ON p.oid=w.oid WHERE to_jsonb(p) IS DISTINCT FROM w.snapshot LIMIT 1) THEN RAISE EXCEPTION '51 coluna/policy predecessor fora allowlist' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM witness51_constraints w LEFT JOIN pg_constraint k ON k.oid=w.oid WHERE NOT(w.conrelid='private47.cadeia'::regclass AND w.conname='cadeia_check') AND to_jsonb(k) IS DISTINCT FROM w.snapshot LIMIT 1) THEN RAISE EXCEPTION '51 constraint predecessor fora allowlist' USING ERRCODE='55000';END IF;
 IF (SELECT count(*) FROM pg_attribute WHERE attrelid='private47.cadeia'::regclass AND attname='obrigacao_adicional' AND atttypid='numeric'::regtype AND atttypmod=983046 AND attnotnull AND NOT attisdropped LIMIT 1)<>1 THEN RAISE EXCEPTION '51 A47 físico inválido' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM witness51_triggers w LEFT JOIN pg_trigger t ON t.oid=w.oid WHERE to_jsonb(t) IS DISTINCT FROM w.snapshot LIMIT 1) THEN RAISE EXCEPTION '51 guarda/trigger predecessor alterado' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM caixa_manutencao45.manifesto m WHERE to_jsonb(m) IS DISTINCT FROM (SELECT snapshot FROM witness51_seals WHERE kind='45' LIMIT 1) LIMIT 1) OR EXISTS(SELECT 1 FROM despesas49.manifesto m WHERE to_jsonb(m) IS DISTINCT FROM (SELECT snapshot FROM witness51_seals WHERE kind='49' LIMIT 1) LIMIT 1) THEN RAISE EXCEPTION '51 selo não afetado45/49 alterado' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM witness51_chain w LEFT JOIN private47.cadeia c ON c.origem_id=w.origem_id WHERE to_jsonb(c)-'obrigacao_adicional' IS DISTINCT FROM w.snapshot OR c.obrigacao_adicional IS DISTINCT FROM 0::numeric LIMIT 1) THEN RAISE EXCEPTION '51 dados47 predecessor alterados além defaultA0' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM pg_class c WHERE c.relnamespace='obrigacoes51'::regnamespace AND c.relkind='r' AND (NOT c.relrowsecurity OR has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE')) LIMIT 1) OR has_schema_privilege('service_role','obrigacoes51','USAGE') THEN RAISE EXCEPTION '51 RLS/ACL privada divergente' USING ERRCODE='55000';END IF;
END $after51$;
